function getDefaultSidebarGroup(buttonId: string): SidebarGroup {
  if ([
    'gestores-default',
    'cadastro-servicos-default',
    'agenda-default',
    'diario-pedidos-dia-default',
    'estado-visual-tecnico-default',
    'informacoes-conhecimento-tecnicos-default',
  ].includes(buttonId)) return 'gestao-tecnica'

  if (['clientes-default', 'fornecedores-default'].includes(buttonId)) return 'parceiros-comercial'

  if (
    [
      'relatorio-servico-default',
      'biblioteca-relatorios-default',
      'relatorios-excluidos-clientes-default',
      'fechamento-relatorios-servicos-default',
    ].includes(buttonId)
  ) {
    return 'documentacao-relatorios'
  }

  if (buttonId === 'biblioteca-pecas-default') {
    return 'pecas-biblioteca'
  }

  if ([
    'orcamentos-avulso-default',
    'orcamento-servico-tecnico-default',
    'orcamentos-pecas-especiais-default',
    'pedido-orcamentos-avulso-default',
  ].includes(buttonId)) return 'gestao-custos'

  if (['registro-despesas-default', 'pagamentos-contador-default'].includes(buttonId)) return 'gestao-financeira'

  if (['mapa-visual-separacao-pecas-default'].includes(buttonId)) return 'almoxarifado-armazem'

  if ([
    'equipamentos-default',
    'desmontados-default',
    'familias-grupos-equipamentos-default',
  ].includes(buttonId)) return 'gestao-industrial'

  if ([
    'pre-checklist-default',
    'checklist-basico-default',
    'checklist-default',
    'gestao-grupos-checklist-default',
    'ordem-preparacao-default',
    'formularios-checklist-tecnicos-default',
    'verificacao-final-entrega-default',
    'familias-grupos-default',
  ].includes(buttonId)) return 'checklist-group'

  if (['clientes-financeiro-default'].includes(buttonId)) return 'gestao-financeira'
  if (['hub-comunicacao-default', 'mensagens-internas-default', 'mensagens-internas-tecnicos-default', 'alerta-mensagens-default'].includes(buttonId)) return 'comunicacao-interna'
  if (['manuais-informacoes-tecnicas-default'].includes(buttonId)) return 'manuais-informacoes-tecnicas'
  if (['biblia-nonato-service-default'].includes(buttonId)) return 'biblia-nonato-service'
  if (['almoxarifado-armazem-default'].includes(buttonId)) return 'almoxarifado-armazem'
  if (
    [
      'cadastro-nonato-service-default',
      'ficha-pagamento-transferencia-default',
      'ficha-fatura-cliente-default',
      'solicitacao-servico-tecnico-default',
    ].includes(buttonId)
  ) {
    return 'empresa-institucional'
  }
  return 'outros'
}

function isSidebarButtonLocked(button: SidebarButton): boolean {
  return SIDEBAR_GROUP_LAUNCHER_IDS.has(button.id)
}

function sidebarGroupChevronClass(isExpanded: boolean): string {
  return `sidebar-nav-chevron${isExpanded ? ' sidebar-nav-chevron--expanded' : ''}`
}

/** Texto do balão ao pairar na sidebar — título visível + descrição opcional. */
function extractSidebarButtonTip(btn: HTMLButtonElement): { title: string; desc: string } {
  const bubble = btn.querySelector('.sidebar-tip-bubble')
  const descRaw = (bubble?.textContent ?? '').replace(/\s+/g, ' ').trim()
  const labelEl =
    btn.querySelector('.sidebar-empresa-entry-title') ||
    btn.querySelector('.sidebar-nav-label-text')
  let title = (labelEl?.textContent ?? '').replace(/\s+/g, ' ').trim()
  if (!title) {
    title = (btn.getAttribute('aria-label') ?? '').trim()
  }
  if (!title) {
    title = (btn.textContent ?? '')
      .replace(/[✓›▸▾]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
  }
  const desc = descRaw && descRaw !== title ? descRaw : ''
  return { title, desc }
}

function SidebarSectionSep({ id, label }: { id: string; label: string }) {
  return (
    <div className="sidebar-section-sep" data-section={id} role="presentation" aria-label={label}>
      <div className="sidebar-section-sep__row">
        <span className="sidebar-section-sep__accent" aria-hidden />
        <span className="sidebar-section-sep__label">{label}</span>
      </div>
      <span className="sidebar-section-sep__line" aria-hidden />
    </div>
  )
}

/** Substitui o botão legado «ficha-cadastral-default» por dois: transferência e fatura (cliente). */
function migrateLegacyFichaCadastralSidebarButtons(buttons: SidebarButton[]): SidebarButton[] {
  if (!buttons.some((b) => b.id === 'ficha-cadastral-default')) return buttons
  return buttons.flatMap((b) => {
    if (b.id !== 'ficha-cadastral-default') return [b]
    const ord = typeof b.order === 'number' ? b.order : 20
    const grp = (b.group || 'empresa-institucional') as SidebarGroup
    return [
      {
        ...b,
        id: 'ficha-pagamento-transferencia-default',
        name: 'FICHA PARA TRANSFERÊNCIA / PAGAMENTO',
        action: 'open-ficha-pagamento-transferencia',
        order: ord,
        translationKey: 'fichaPagamentoTransferenciaTitle',
        group: grp,
        customName: false,
      },
      {
        ...b,
        id: 'ficha-fatura-cliente-default',
        name: 'FICHA PARA O CLIENTE EMITIR FATURA',
        action: 'open-ficha-fatura-cliente',
        order: ord + 1,
        translationKey: 'fichaFaturaClienteTitle',
        group: grp,
        customName: false,
      },
    ]
  })
}

function normalizeSidebarButtons(buttons: SidebarButton[]): SidebarButton[] {
  const sorted = [...buttons].sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
  const grouped = new Map<SidebarGroup, SidebarButton[]>()
  for (const group of SIDEBAR_GROUPS) grouped.set(group, [])

  for (const button of sorted) {
    if (isSidebarButtonLocked(button)) continue
    const group = button.group || getDefaultSidebarGroup(button.id)
    grouped.get(group)!.push({ ...button, group })
  }

  const normalizedMovable = SIDEBAR_GROUPS.flatMap((group) => grouped.get(group) || [])
  const movableById = new Map(normalizedMovable.map((button) => [button.id, button]))

  return sorted.map((button) => {
    if (isSidebarButtonLocked(button)) return button
    const normalized = movableById.get(button.id)
    return normalized ? { ...normalized, order: normalizedMovable.findIndex((entry) => entry.id === button.id) } : button
  })
}

/** Subsecções fixas dentro da Gestão Financeira (sidebar e hub) — botões desconhecidos ficam em «outros». */
function getGestaoFinanceiraUiSubgroup(buttonId: string): 'clientes' | 'despesas' | 'outros' {
  if (buttonId === 'clientes-financeiro-default') return 'clientes'
  if (
    buttonId === 'registro-despesas-default' ||
    buttonId === 'comprovantes-despesas-default' ||
    buttonId === 'pagamentos-contador-default'
  )
    return 'despesas'
  return 'outros'
}

