const AGENDA_FILTRO_BAR_STYLE: React.CSSProperties = {
  display: 'flex',
  flexWrap: 'wrap',
  alignItems: 'flex-end',
  gap: 12,
  width: '100%',
}

function isAgendamentoCancelado(ag: Agendamento): boolean {
  return normalizeStatusAgendamento(ag) === 'cancelado'
}

function estiloMarcadorAgendamentoCancelado(): React.CSSProperties {
  return {
    background: AGENDA_CANCELADO_BG,
    border: `2px solid ${AGENDA_CANCELADO_BORDA}`,
    boxShadow: AGENDA_CANCELADO_SOMBRA,
    color: '#ffffff',
    fontWeight: 700,
    textDecoration: 'line-through',
    textShadow: '0 1px 2px rgba(0,0,0,0.5)',
  }
}

function rotuloAgendaPainelSituacao(
  id: 'exec' | 'agend' | 'pre' | 'pessoal' | 'pend' | 'canc' | 'done',
  tr?: Record<string, string | undefined>
): string {
  switch (id) {
    case 'exec':
      return tr?.agendaPainelEmExecucao || 'Em execução'
    case 'agend':
      return tr?.agendaPainelAgendados || 'Agendados (confirmados)'
    case 'pre':
      return tr?.agendaPainelPreAgendados || 'Pré-agendados'
    case 'pessoal':
      return tr?.agendaPainelAssuntosPessoais || 'Assuntos pessoais'
    case 'pend':
      return tr?.agendaPainelPendentes || 'Pendentes (ag. técnico)'
    case 'canc':
      return tr?.agendaPainelCancelados || 'Cancelados'
    default:
      return tr?.agendaPainelConcluidosRecentes || 'Concluídos (recentes)'
  }
}

type EquipamentoCliente = {
  /** ID ou código de referência (opcional). Se vazio na 1.ª gravação, gera-se um ID técnico (UUID). Distinto do n.º de série. */
  id?: string
  tipoEquipamento: string
  modelo: string
  marca: string
  numeroSerie: string
  familia: string
  grupo: string
  photo?: string
  coverPhoto?: string
  photoLibrary?: string[]
  manualPdf?: string
  itemsIncluded?: string[]
  relatorios?: RelatorioEquipamento[]
}

type Cliente = {
  id: string
  /** Código legível (ex.: NS000042) — gerado automaticamente */
  codigoCliente?: string
  nomeEmpresa: string
  morada: string
  localidade: string
  conselho: string
  pais: string
  codigoPostal: string
  freguesia: string
  numeroContribuicaoFiscal: string
  telefones: string
  email: string
  contato: string
  photo?: string
  equipamentos: EquipamentoCliente[]
  relatorios?: { [equipamentoId: string]: RelatorioServico[] } // Relatórios organizados por equipamento
  isDevedor?: boolean // Indica se o cliente é devedor
  saldoPendente?: number // Saldo pendente do cliente
  /** Quantidade de relatórios de serviço com situação «não pago» no fluxo financeiro */
  relatoriosNaoPagoCount?: number
  /** Relatório mais recente (por data) ainda «não pago»/devedor — destaque fino no cadastro até regularizar */
  ultimoRelatorioDevedorId?: string
  /** Formulários de solicitação técnica devolvidos (PDF/imagem), associados ao registo do cliente */
  anexosSolicitacaoServico?: SolicitacaoDocDevolvidoCliente[]
  /** Grupo do Cadastro de Serviços (tabela HTT/KRC/…) aplicada a este cliente */
  grupoTarifaId?: string
  /** KM de ida predefinidos — preenchidos no relatório de serviço ao escolher o cliente */
  kmIdaPadrao?: string
  /** KM de retorno predefinidos — preenchidos no relatório de serviço ao escolher o cliente */
  kmRetornoPadrao?: string
  /** Pessoa física ou jurídica — usado no formulário de cadastro */
  tipoCliente?: 'fisica' | 'juridica'
}

function findClienteByRelatorio(clientes: Cliente[], rel: RelatorioServico): Cliente | undefined {
  const cid = (rel.clienteId || '').trim()
  if (cid) {
    const byId = clientes.find((c) => c.id === cid)
    if (byId) return byId
  }
  const nome = (rel.cliente || '').trim().toLowerCase()
  if (!nome) return undefined
  return clientes.find((c) => (c.nomeEmpresa || '').trim().toLowerCase() === nome)
}

function nomeGrupoTarifaServico(servicoGrupos: ServicoCadastroGrupo[], grupoId?: string): string {
  if (!grupoId) return ''
  return servicoGrupos.find((g) => g.id === grupoId)?.nome || ''
}

/** true = ID gerado pela app (UUID ou prefixo eqc-), não código próprio do utilizador. */
function equipamentoClienteIdETecnicoGerado(id: string | undefined): boolean {
  const t = String(id ?? '').trim()
  if (!t) return true
  if (/^eqc-/i.test(t)) return true
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89abAB][0-9a-f]{3}-[0-9a-f]{12}$/i.test(t)
}

/** ID no cabeçalho do protocolo/PDF: código próprio do cliente; senão ID do armazém pela série. */
function idEquipamentoVisivelParaProtocolo(eq: EquipamentoCliente | undefined, equipamentosArmazem: Equipamento[]): string {
  if (!eq) return ''
  return resolverIdEquipamentoVisivelCliente(eq, equipamentosArmazem)
}

function cmpClienteRelatorioFinanceiro(a: string, b: string): number {
  return (a || '').localeCompare(b || '', undefined, { sensitivity: 'base', numeric: true })
}

function normalizeOsNumeroRelatorio(numero: string | undefined | null): string {
  return String(numero ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '')
}

/** Relatório com fechamento guardado na Biblioteca (pode ainda estar em aberto na lista principal). */
function relatorioEstaNaBibliotecaArquivo(
  r: RelatorioServico,
  fechamentosGuardadosBibliotecaIds: string[]
): boolean {
  return fechamentosGuardadosBibliotecaIds.includes(r.id)
}

/**
 * Sai da pasta «Relatório de Serviço» só quando está na Biblioteca E «Serviço concluído».
 * Na Biblioteca sem concluir (ex.: fechamento gravado) continua visível na lista.
 */
function relatorioSaiDaListaPrincipalRelatorios(
  r: RelatorioServico,
  fechamentosGuardadosBibliotecaIds: string[]
): boolean {
  if (!r.servicoConcluido) return false
  return relatorioEstaNaBibliotecaArquivo(r, fechamentosGuardadosBibliotecaIds)
}

/** Relatórios ainda visíveis no separador «Relatório de Serviço». */
function relatoriosServicoForaDaBiblioteca(
  relatoriosServico: RelatorioServico[],
  fechamentosGuardadosBibliotecaIds: string[]
): RelatorioServico[] {
  return relatoriosServico.filter(
    (r) => !relatorioSaiDaListaPrincipalRelatorios(r, fechamentosGuardadosBibliotecaIds)
  )
}

function classNameResumoCobrancaPorFase(fase: 'laranja' | 'azul' | 'verde' | 'biblioteca'): string {
  if (fase === 'biblioteca') return 'relatorio-resumo-cobranca-wrap--biblioteca'
  if (fase === 'verde') return 'relatorio-resumo-cobranca-wrap--verde'
  if (fase === 'azul') return 'relatorio-resumo-cobranca-wrap--azul'
  return 'relatorio-resumo-cobranca-wrap--laranja'
}

/** Alinha IDs duplicados (mesmo n.º OS) na Biblioteca — só acrescenta cópias já concluídas. */
function repararIdsGuardadosBiblioteca(
  guardAtual: string[],
  fechamentosRelatorios: Record<string, FechamentoItem[]>,
  relatoriosServico: RelatorioServico[]
): string[] {
  const porId = new Map(relatoriosServico.map((r) => [r.id, r]))
  const set = new Set(guardAtual)
  const normToIds = new Map<string, string[]>()
  for (const r of relatoriosServico) {
    if (!r.servicoConcluido) continue
    const n = normalizeOsNumeroRelatorio(r.numero)
    if (!n) continue
    const arr = normToIds.get(n) ?? []
    arr.push(r.id)
    normToIds.set(n, arr)
  }
  for (const ids of normToIds.values()) {
    if (!ids.some((id) => set.has(id))) continue
    for (const id of ids) {
      const rel = porId.get(id)
      if (!rel?.servicoConcluido) continue
      const itens = fechamentosRelatorios[id]
      if (Array.isArray(itens) && itens.length > 0) set.add(id)
    }
  }
  return [...set]
}

/** Relatórios de serviço com fechamento guardado na biblioteca (lista global ordenada A–Z por cliente e nº). */
function relatoriosComFechamentoNaBibliotecaOrdenados(
  relatoriosServico: RelatorioServico[],
  clientes: Cliente[],
  fechamentosGuardadosBibliotecaIds: string[],
  fechamentosRelatorios: Record<string, FechamentoItem[]>
): RelatorioServico[] {
  return relatoriosServico
    .filter(
      r =>
        Boolean(r.clienteId) &&
        fechamentosGuardadosBibliotecaIds.includes(r.id) &&
        Array.isArray(fechamentosRelatorios[r.id]) &&
        fechamentosRelatorios[r.id]!.length > 0
    )
    .sort((a, b) => {
      const ca = clientes.find(c => c.id === a.clienteId)?.nomeEmpresa || a.cliente || ''
      const cb = clientes.find(c => c.id === b.clienteId)?.nomeEmpresa || b.cliente || ''
      const byC = cmpClienteRelatorioFinanceiro(ca, cb)
      if (byC !== 0) return byC
      return cmpClienteRelatorioFinanceiro(String(a.numero ?? ''), String(b.numero ?? ''))
    })
}

type RelatorioFechadoBibliotecaRow = {
  relatorio: RelatorioServico
  clienteNome: string
  itens: FechamentoItem[]
}

/** Todos os relatórios já fechados / arquivados na biblioteca — para secção «Ver» e «Editar». */
function buildRelatoriosFechadosBibliotecaLista(
  relatoriosServico: RelatorioServico[],
  clientes: Cliente[],
  fechamentosGuardadosBibliotecaIds: string[],
  fechamentosRelatorios: Record<string, FechamentoItem[] | undefined>
): RelatorioFechadoBibliotecaRow[] {
  const idSet = new Set(fechamentosGuardadosBibliotecaIds)
  return relatoriosServico
    .filter((r) => idSet.has(r.id))
    .map((r) => {
      const cliente =
        clientes.find((c) => c.id === r.clienteId) ||
        findClienteByRelatorio(clientes, r)
      return {
        relatorio: r,
        clienteNome: String(cliente?.nomeEmpresa || r.cliente || '—').trim() || '—',
        itens: Array.isArray(fechamentosRelatorios[r.id]) ? fechamentosRelatorios[r.id]! : [],
      }
    })
    .sort((a, b) => {
      const byC = cmpBibliotecaLocale(a.clienteNome, b.clienteNome)
      if (byC !== 0) return byC
      return cmpBibliotecaLocale(String(a.relatorio.numero ?? ''), String(b.relatorio.numero ?? ''))
    })
}

type RelatorioFechadoBibliotecaGrupo = {
  key: string
  clienteNome: string
  rows: RelatorioFechadoBibliotecaRow[]
}

function groupRelatoriosFechadosPorCliente(
  lista: RelatorioFechadoBibliotecaRow[]
): RelatorioFechadoBibliotecaGrupo[] {
  const map = new Map<string, RelatorioFechadoBibliotecaRow[]>()
  for (const row of lista) {
    const key = (row.clienteNome || '—').trim().toLowerCase()
    if (!map.has(key)) map.set(key, [])
    map.get(key)!.push(row)
  }
  return Array.from(map.entries())
    .map(([key, rows]) => ({
      key,
      clienteNome: rows[0]?.clienteNome || '—',
      rows: [...rows].sort((a, b) =>
        cmpBibliotecaLocale(String(a.relatorio.numero ?? ''), String(b.relatorio.numero ?? ''))
      ),
    }))
    .sort((a, b) => cmpBibliotecaLocale(a.clienteNome, b.clienteNome))
}

type BibliotecaRelatoriosClienteRow = {
  cliente: Cliente
  equipamentos: Array<{ equipamento: EquipamentoCliente; equipamentoKey: string; relatorios: RelatorioServico[] }>
  despesas: Array<{ relatorio: RelatorioServico; itens: FechamentoItem[] }>
}

/** Pesquisa na biblioteca: cliente, equipamento, n.º/tipo/técnico do relatório ou fechamento. */
function bibliotecaRelatoriosRowMatchesBusca(row: BibliotecaRelatoriosClienteRow, q: string): boolean {
  const nq = q.trim().toLowerCase()
  if (!nq) return true
  const { cliente, equipamentos, despesas } = row
  const nome = String(cliente.nomeEmpresa || '').toLowerCase()
  const nif = String((cliente as { numeroContribuicaoFiscal?: string }).numeroContribuicaoFiscal || '').toLowerCase()
  const telefones = String((cliente as { telefones?: string }).telefones || '').toLowerCase()
  const email = String((cliente as { email?: string }).email || '').toLowerCase()
  if (nome.includes(nq) || nif.includes(nq) || telefones.includes(nq) || email.includes(nq)) return true
  if (nomesClienteCorrespondem(nq, cliente.nomeEmpresa || '')) return true
  for (const eq of equipamentos) {
    const eqLabel = `${eq.equipamento.modelo || ''} ${eq.equipamento.marca || ''} ${eq.equipamento.numeroSerie || ''} ${eq.equipamentoKey || ''}`.toLowerCase()
    if (eqLabel.includes(nq)) return true
    for (const rel of eq.relatorios) {
      if (
        String(rel.numero ?? '').toLowerCase().includes(nq) ||
        String(rel.tipoServico ?? '').toLowerCase().includes(nq) ||
        String(rel.tecnico ?? '').toLowerCase().includes(nq) ||
        String(rel.cliente ?? '').toLowerCase().includes(nq) ||
        String(rel.maquinaModelo ?? '').toLowerCase().includes(nq)
      ) return true
    }
  }
  for (const { relatorio } of despesas) {
    if (
      String(relatorio.numero ?? '').toLowerCase().includes(nq) ||
      String(relatorio.cliente ?? '').toLowerCase().includes(nq) ||
      String(relatorio.maquinaModelo ?? '').toLowerCase().includes(nq)
    ) return true
  }
  return false
}

function cmpBibliotecaLocale(a: string, b: string): number {
  return (a || '').localeCompare(b || '', undefined, { sensitivity: 'base', numeric: true })
}

function ordenarRelatoriosBiblioteca(relatorios: RelatorioServico[]): RelatorioServico[] {
  return [...relatorios].sort((a, b) => {
    const byNum = cmpBibliotecaLocale(String(a.numero ?? ''), String(b.numero ?? ''))
    if (byNum !== 0) return byNum
    return cmpBibliotecaLocale(String(a.tipoServico ?? ''), String(b.tipoServico ?? ''))
  })
}

/** Cliente com pelo menos um relatório de serviço ou de despesas na biblioteca. */
function bibliotecaRowTemConteudo(row: BibliotecaRelatoriosClienteRow): boolean {
  if (row.despesas.length > 0) return true
  return row.equipamentos.some((eq) => eq.relatorios.length > 0)
}

/** Monta a árvore cliente → equipamentos (todos os registados) → relatórios de serviço + despesas. */
function buildBibliotecaRelatoriosPorCliente(
  clientes: Cliente[],
  relatoriosServico: RelatorioServico[],
  fechamentosRelatorios: Record<string, FechamentoItem[] | undefined>,
  fechamentosGuardadosBibliotecaIds: string[],
  equipamentosArmazem: EquipamentoArmazemIdLookup[] = []
): BibliotecaRelatoriosClienteRow[] {
  const rows: BibliotecaRelatoriosClienteRow[] = []

  for (const cliente of clientes) {
    const equipMap = new Map<
      string,
      { equipamento: EquipamentoCliente; equipamentoKey: string; relatorios: RelatorioServico[] }
    >()

    const putEquip = (equipamento: EquipamentoCliente, equipamentoKey: string) => {
      const key = String(equipamentoKey || '').trim()
      if (!key) return
      const rels = ordenarRelatoriosBiblioteca(cliente.relatorios?.[key] || [])
      equipMap.set(key, { equipamento, equipamentoKey: key, relatorios: rels })
    }

    if (cliente.equipamentos?.length) {
      for (const eq of cliente.equipamentos) {
        const key =
          String(eq.numeroSerie || '').trim() ||
          `${String(eq.modelo || '').trim()} ${String(eq.marca || '').trim()}`.trim() ||
          String(eq.id || '').trim()
        if (key) putEquip(eq, key)
      }
    }

    if (cliente.relatorios && typeof cliente.relatorios === 'object') {
      for (const equipamentoKey of Object.keys(cliente.relatorios)) {
        const key = String(equipamentoKey || '').trim()
        if (!key) continue
        if (equipMap.has(key)) {
          const entry = equipMap.get(key)!
          entry.relatorios = ordenarRelatoriosBiblioteca(cliente.relatorios[key] || [])
          continue
        }
        const equipamento =
          cliente.equipamentos?.find(
            eq =>
              eq.numeroSerie === key ||
              `${String(eq.modelo || '').trim()} ${String(eq.marca || '').trim()}`.trim() === key
          ) ||
          ({
            id: `legacy-${cliente.id}-${key}`,
            modelo: key,
            marca: '',
            numeroSerie: key,
          } as EquipamentoCliente)
        putEquip(equipamento, key)
      }
    }

    const equipamentos = Array.from(equipMap.values()).sort((a, b) => {
      const sa = `${a.equipamento.modelo || ''} ${a.equipamento.marca || ''} ${a.equipamento.numeroSerie || ''}`.trim()
      const sb = `${b.equipamento.modelo || ''} ${b.equipamento.marca || ''} ${b.equipamento.numeroSerie || ''}`.trim()
      return cmpBibliotecaLocale(sa, sb)
    })

    const relatoriosDoCliente = relatoriosServico.filter(
      (r) =>
        r.clienteId === cliente.id ||
        resolverClienteIdRelatorioFlexivel(r, clientes) === cliente.id ||
        nomesClienteCorrespondem(String(r.cliente ?? ''), String(cliente.nomeEmpresa ?? ''))
    )

    /** Garante relatórios de serviço na pasta (fonte: relatoriosServico, não só cliente.relatorios). */
    for (const rel of relatoriosDoCliente) {
      let keys = equipamentosClienteParaBiblioteca(
        normalizarEquipamentosRelatorio(rel),
        equipamentosArmazem,
        cliente.equipamentos ?? []
      )
      if (keys.length === 0) {
        const legadoSn = String(rel.numeroMaquina ?? '').trim()
        const legadoMod = String(rel.maquinaModelo ?? '').trim()
        const legadoId = String(rel.equipamentoId ?? '').trim()
        if (legadoSn) keys = [legadoSn]
        else if (legadoMod) keys = [legadoMod]
        else if (legadoId) keys = [legadoId]
        else keys = ['—']
      }

      for (const key of keys) {
        const k = String(key || '').trim() || '—'
        if (!equipMap.has(k)) {
          const equipamento =
            cliente.equipamentos?.find(
              (eq) =>
                eq.numeroSerie === k ||
                `${String(eq.modelo || '').trim()} ${String(eq.marca || '').trim()}`.trim() === k
            ) ||
            ({
              id: `bib-${cliente.id}-${k}`,
              modelo: k === '—' ? 'Equipamento' : k,
              marca: '',
              numeroSerie: k === '—' ? '' : k,
            } as EquipamentoCliente)
          equipMap.set(k, { equipamento, equipamentoKey: k, relatorios: [] })
        }
        const entry = equipMap.get(k)!
        const ja = entry.relatorios.some((item) => item.id === rel.id)
        entry.relatorios = ordenarRelatoriosBiblioteca(
          ja ? entry.relatorios.map((item) => (item.id === rel.id ? rel : item)) : [...entry.relatorios, rel]
        )
      }
    }

    const despesas: Array<{ relatorio: RelatorioServico; itens: FechamentoItem[] }> = []
    for (const rel of relatoriosDoCliente) {
      const itens = fechamentosRelatorios[rel.id]
      if (itens && itens.length > 0 && fechamentosGuardadosBibliotecaIds.includes(rel.id)) {
        despesas.push({ relatorio: rel, itens })
      }
    }
    despesas.sort((a, b) =>
      cmpBibliotecaLocale(String(a.relatorio.numero ?? ''), String(b.relatorio.numero ?? ''))
    )

    rows.push({ cliente, equipamentos, despesas })
  }

  const idsIndexados = new Set<string>()
  for (const row of rows) {
    for (const eq of row.equipamentos) {
      for (const r of eq.relatorios) idsIndexados.add(r.id)
    }
    for (const d of row.despesas) idsIndexados.add(d.relatorio.id)
  }

  const orfaos = relatoriosServicoOrfaosNaBiblioteca(relatoriosServico, idsIndexados)
  const orfaosPorNome = agruparRelatoriosOrfaosPorNome(orfaos)
  for (const [, relsOrfaos] of orfaosPorNome) {
    if (!relsOrfaos.length) continue
    const nomeOrfaos = String(relsOrfaos[0]?.cliente ?? '').trim() || 'Relatórios recuperados'
    const clienteOrfaos: Cliente = {
      id: `bib-orfaos-${nomeOrfaos.toLowerCase().replace(/\s+/g, '-').slice(0, 48)}`,
      nomeEmpresa: nomeOrfaos,
      equipamentos: [],
      relatorios: {},
    } as Cliente
    const equipMapOrfaos = new Map<
      string,
      { equipamento: EquipamentoCliente; equipamentoKey: string; relatorios: RelatorioServico[] }
    >()
    for (const rel of relsOrfaos) {
      const k =
        String(rel.numeroMaquina ?? '').trim() ||
        String(rel.maquinaModelo ?? '').trim() ||
        String(rel.equipamentoId ?? '').trim() ||
        '—'
      if (!equipMapOrfaos.has(k)) {
        equipMapOrfaos.set(k, {
          equipamento: {
            id: `orph-eq-${k}`,
            modelo: k === '—' ? 'Equipamento' : k,
            marca: '',
            numeroSerie: k === '—' ? '' : k,
          } as EquipamentoCliente,
          equipamentoKey: k,
          relatorios: [],
        })
      }
      const entry = equipMapOrfaos.get(k)!
      if (!entry.relatorios.some((item) => item.id === rel.id)) {
        entry.relatorios = ordenarRelatoriosBiblioteca([...entry.relatorios, rel])
      }
    }
    const equipamentosOrfaos = Array.from(equipMapOrfaos.values())
    const despesasOrfaos: Array<{ relatorio: RelatorioServico; itens: FechamentoItem[] }> = []
    for (const rel of relsOrfaos) {
      const itens = fechamentosRelatorios[rel.id]
      if (itens && itens.length > 0 && fechamentosGuardadosBibliotecaIds.includes(rel.id)) {
        despesasOrfaos.push({ relatorio: rel, itens })
      }
    }
    rows.push({ cliente: clienteOrfaos, equipamentos: equipamentosOrfaos, despesas: despesasOrfaos })
  }

  rows.sort((x, y) => cmpBibliotecaLocale(x.cliente.nomeEmpresa || '', y.cliente.nomeEmpresa || ''))
  return rows
}

function equipamentosClienteDoRelatorioDespesas(
  rel: { clienteId?: string; cliente?: string },
  clientes: Cliente[]
) {
  const cid = rel.clienteId || resolverClienteIdRelatorio(rel as RelatorioServico, clientes)
  return clientes.find((c) => c.id === cid)?.equipamentos ?? []
}

function EquipamentosRelatorioDespesasInline({
  relatorio,
  clientes,
  equipamentosArmazem,
}: {
  relatorio: RelatorioServico
  clientes: Cliente[]
  equipamentosArmazem: EquipamentoArmazemIdLookup[]
}) {
  const clEq = equipamentosClienteDoRelatorioDespesas(relatorio, clientes)
  const linhas = linhasTextoEquipamentosRelatorioDespesas(relatorio, equipamentosArmazem, clEq)
  if (linhas.length <= 1) return <>{linhas[0]?.texto ?? '—'}</>
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      {linhas.map((l) => (
        <div key={l.numero} style={{ lineHeight: 1.35 }}>
          <span style={{ opacity: 0.85 }}>Equip. {l.numero}:</span> {l.texto}
        </div>
      ))}
    </div>
  )
}

function normalizarTextoFaturaBusca(s: string): string {
  return s.trim().toLowerCase().replace(/\s+/g, '')
}

/**
 * Correspondência exata (normalizada) ou parcial: exige pelo menos 2 caracteres na consulta
 * para evitar coincidências com um único dígito/letra.
 */
function numeroFaturaCorrespondeConsulta(numeroGuardado: string, consulta: string): boolean {
  const a = normalizarTextoFaturaBusca(numeroGuardado)
  const b = normalizarTextoFaturaBusca(consulta)
  if (!a || !b) return false
  if (a === b) return true
  if (b.length < 2) return false
  return a.includes(b) || b.includes(a)
}

// Protocolo de Serviço: antes/depois com texto, imagens e peças trocadas
type ProtocoloBloco = {
  /** Identificador estável por bloco (evita FileReader async gravar no índice errado). */
  id?: string
  tipo: 'texto' | 'imagens' | 'acao'
  /** Cabeçalho desta acção / secção (PDF e formulário). */
  titulo?: string
  texto?: string
  imagens?: string[] // máx. 2, uma ao lado da outra (bloco imagens ou acção)
  /** Apenas `acao`: ordem entre quadro de imagens e balão de texto. */
  ordemConteudo?: 'texto_primeiro' | 'imagens_primeiro'
  /** Apenas `acao`: estado técnico visível no PDF (Bom / Reparar / Substituir / N/D). */
  estadoAcao?: 'bom' | 'reparar' | 'substituir' | 'nd'
}

function newProtocoloBlocoId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID()
  return `bloco-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

function ensureProtocoloBlocosIds(blocos: ProtocoloBloco[]): ProtocoloBloco[] {
  return blocos.map((raw) => {
    const b = raw as ProtocoloBloco
    const tipo = b.tipo === 'imagens' || b.tipo === 'acao' || b.tipo === 'texto' ? b.tipo : 'texto'
    const base: ProtocoloBloco = {
      ...b,
      tipo,
      imagens: tipo === 'acao' || tipo === 'imagens' ? (Array.isArray(b.imagens) ? b.imagens : []) : b.imagens,
      ordemConteudo:
        tipo === 'acao' && (b.ordemConteudo === 'imagens_primeiro' || b.ordemConteudo === 'texto_primeiro')
          ? b.ordemConteudo
          : tipo === 'acao'
            ? 'texto_primeiro'
            : undefined,
      estadoAcao:
        tipo === 'acao' && (b.estadoAcao === 'bom' || b.estadoAcao === 'reparar' || b.estadoAcao === 'substituir' || b.estadoAcao === 'nd')
          ? b.estadoAcao
          : undefined,
    }
    return base.id ? base : { ...base, id: newProtocoloBlocoId() }
  })
}

/** Primeiro número com 9–15 dígitos (WhatsApp wa.me) a partir do campo telefones do cliente */
function telefoneDigitsParaWa(telefones: string): string {
  const s = String(telefones || '')
  const all = s.replace(/\D/g, '')
  if (all.length >= 10 && all.length <= 15) return all
  if (all.length === 9) return all
  const parts = s.split(/[/;,|]+/)
  for (const part of parts) {
    const d = part.replace(/\D/g, '')
    if (d.length >= 10 && d.length <= 15) return d
    if (d.length === 9) return d
  }
  return all.length >= 9 ? all : ''
}

