      'cadastro-nonato-service': 'open-cadastro-nonato-service',
      'ficha-pagamento-transferencia': 'open-ficha-pagamento-transferencia',
      'ficha-fatura-cliente': 'open-ficha-fatura-cliente',
      administrador: 'open-administrador',
