  const categoriasGestaoFiltradas = useMemo(() => {
    let list = filtrarPorNomeBusca(categoriasPecasAlfabeto, gerenciarCategoriasBusca)
    if (gerenciarCategoriasLetra) {
      list = list.filter((c) => getLetraAlfabetoNome(c.nome) === gerenciarCategoriasLetra)
    }
    return list
  }, [categoriasPecasAlfabeto, gerenciarCategoriasBusca, gerenciarCategoriasLetra])
  const primeiraExecUltimaSelecaoBiblioteca = useRef(true)
  useEffect(() => {
    if (primeiraExecUltimaSelecaoBiblioteca.current) {
      primeiraExecUltimaSelecaoBiblioteca.current = false
      if (ultimoGrupoSelecionado === '' && ultimoSubgrupoSelecionado === '') return
    }
    void saveData(BIBLIOTECA_PECAS_ULTIMA_SELECAO_KEY, {
      categoriaId: ultimoGrupoSelecionado,
      subcategoriaId: ultimoSubgrupoSelecionado,
    })
  }, [ultimoGrupoSelecionado, ultimoSubgrupoSelecionado])
  useEffect(() => {
    if (!showBibliotecaPecasForm) return
    let gid = pecaBibliotecaForm.categoriaId || ultimoGrupoSelecionado || ''
    const sid =
      pecaBibliotecaForm.subcategoriaId ||
      (gid === ultimoGrupoSelecionado ? ultimoSubgrupoSelecionado : '') ||
      ''
    if (!gid && pecaBibliotecaForm.categoria?.trim() && categoriasPecas.length) {
      const alvo = pecaBibliotecaForm.categoria.trim().toLowerCase()
      const porNome = categoriasPecas.find((c) => (c.nome || '').trim().toLowerCase() === alvo)
      if (porNome) gid = porNome.id
    }
    if (!gid && !sid) {
      setPecaBibliotecaForm((prev) => (prev.numeroSequenciaGrupo ? { ...prev, numeroSequenciaGrupo: '' } : prev))
      return
    }
    if (editingPecaBiblioteca) {
      const oldKey = chaveSequenciaNumeroPecaBiblioteca(editingPecaBiblioteca, categoriasPecas)
      const newKey = chaveSequenciaNumeroPecaBiblioteca({ categoriaId: gid, subcategoriaId: sid }, categoriasPecas)
      const existente = parseNumeroSequenciaPecaBiblioteca(editingPecaBiblioteca.numeroSequenciaGrupo)
      if (oldKey === newKey && existente > 0) {
        const fmt = formatNumeroSequenciaPecaBiblioteca(existente)
        setPecaBibliotecaForm((prev) =>
          prev.numeroSequenciaGrupo === fmt ? prev : { ...prev, numeroSequenciaGrupo: fmt }
        )
        return
      }
    }
    const next = proximoNumeroSequenciaPecaBiblioteca(
      gid,
      sid,
      pecasBiblioteca,
      editingPecaBiblioteca?.id,
      categoriasPecas
    )
    setPecaBibliotecaForm((prev) =>
      prev.numeroSequenciaGrupo === next ? prev : { ...prev, numeroSequenciaGrupo: next }
    )
  }, [
    showBibliotecaPecasForm,
    pecaBibliotecaForm.categoriaId,
    pecaBibliotecaForm.subcategoriaId,
    pecaBibliotecaForm.categoria,
    ultimoGrupoSelecionado,
    ultimoSubgrupoSelecionado,
    editingPecaBiblioteca,
    pecasBiblioteca,
    categoriasPecas,
  ])
  useEffect(() => {
    if (pecasBiblioteca.length === 0) return
    const { lista, alterou } = garantirNumerosSequenciaPecaBiblioteca(pecasBiblioteca, categoriasPecas)
    if (!alterou) return
    setPecasBiblioteca(lista)
    void savePecasBibliotecaLocally(lista as unknown[])
  }, [pecasBiblioteca, categoriasPecas])

  /** Atualiza UI quando fotos chegam em segundo plano — funde com estado local (não substitui classificações). */
  useEffect(() => {
    const onImagens = (ev: Event) => {
      const pecas = (ev as CustomEvent<{ pecas?: unknown[] }>).detail?.pecas
      if (!Array.isArray(pecas) || pecas.length === 0) return
      setPecasBiblioteca((prev) => {
        const raw = (pecas as PecaBiblioteca[]).map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca))
        const merged = mergePecasBibliotecaArrays(raw, prev) as PecaBiblioteca[]
        const { lista } = garantirNumerosSequenciaPecaBiblioteca(merged, categoriasPecas)
        return lista
      })
    }
    window.addEventListener('nonato-pecas-imagens-hidratadas', onImagens)
    return () => window.removeEventListener('nonato-pecas-imagens-hidratadas', onImagens)
  }, [categoriasPecas])
