  // Função para criar backup completo (v2 — todas as chaves nonato-* + IndexedDB)
  const handleCreateBackup = async () => {
    try {
      const data = await collectFullBackupData()
      const envelope = buildBackupEnvelope(data)
      const jsonStr = JSON.stringify(envelope, null, 2)
      const dateStr = new Date().toISOString().split('T')[0]
      const fileName = `${(t as any).backupFileName || 'backup'}-${dateStr}.json`

      if (backupMethod === 'server' && backupServerUrl.trim()) {
        const url = backupServerUrl.trim()
        if (url.startsWith('http://') || url.startsWith('https://')) {
          try {
            const response = await fetch(url, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: jsonStr,
            })
            if (response.ok) {
              alert(t.backupSendSuccess)
            } else {
              throw new Error(`Erro HTTP ${response.status}`)
            }
          } catch (error) {
            alert(((t as any).backupSendError || 'Erro ao enviar backup') + ': ' + (error as Error).message)
            return
          }
        } else {
          downloadBackupJson(envelope, fileName)
          pushManualDataBackupFromEnvelope(envelope)
          alert(((t as any).backupSuccess || 'Backup realizado com sucesso!') + '\n' + ((t as any).backupDownloaded || 'Backup baixado'))
        }
      } else {
        downloadBackupJson(envelope, fileName)
        const stored = pushManualDataBackupFromEnvelope(envelope)
        let diskMsg = ''
        try {
          const saveRes = await fetch('/api/backup-data/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: jsonStr,
          })
          const saveResult = await saveRes.json().catch(() => ({}))
          if (saveRes.ok && saveResult.jsonFolderAbsolute) {
            diskMsg =
              '\n\n✓ Guardado na pasta do projeto:\n' +
              saveResult.jsonFolderAbsolute +
              '\\' +
              (saveResult.fileName || fileName)
          } else if (!saveRes.ok && saveResult.error) {
            diskMsg = '\n\n(Aviso: não foi possível guardar no disco — ' + saveResult.error + ')'
          }
        } catch {
          diskMsg =
            '\n\n(Aviso: não guardou na pasta do projeto — verifique se usa http://localhost:3000 com npm run dev.)\n' +
            'Os ficheiros podem estar em Descargas — execute SINCRONIZAR-BACKUPS-DESCARGAS.bat'
        }
        alert(
          ((t as any).backupSuccess || 'Backup realizado com sucesso!') +
            '\n' +
            ((t as any).backupDownloaded || 'Backup baixado') +
            `\n\nChaves incluídas: ${Object.keys(data).length} (cadastro, serviços, relatórios, peças, etc.)` +
            (stored.ok ? '\n\n✓ Registado nos últimos 5 backups JSON no navegador.' : '') +
            diskMsg
        )
      }
    } catch (error) {
      alert(t.errorCreatingBackup + ': ' + (error as Error).message)
    }
  }

  // Função para criar backup automático (salva no localStorage)
  const createAutoBackup = useCallback(async () => {
    try {
      return await createAutoBackupEntry()
    } catch (error) {
      console.error('Erro ao criar backup automático:', error)
      return false
    }
  }, [])

  /** Cópias automáticas periódicas no navegador (além das que ocorrem ao guardar relatórios, etc.). */
  useEffect(() => {
    if (typeof window === 'undefined' || isDemoMode || !autoBackupEnabled) return
    const minutes = Math.max(5, Number.isFinite(autoBackupInterval) ? autoBackupInterval : 30)
    const id = window.setInterval(() => {
      void createAutoBackup()
    }, minutes * 60 * 1000)
    return () => window.clearInterval(id)
  }, [autoBackupEnabled, autoBackupInterval, isDemoMode, createAutoBackup])

  // Função para restaurar backup automático (v1 ou v2 — restauro completo)
  const restoreAutoBackup = async (backup: { timestamp: number; data?: any }) => {
    try {
      if (!backup?.data) {
        alert(t.invalidBackup || 'Backup inválido')
        return false
      }
      const envelope = backup.data.data ? backup.data : { data: backup.data }
      const keyMap = normalizeBackupFile(envelope)
      const result = await restoreFullBackup(keyMap)
      if (!result.ok) {
        alert(result.error || t.errorRestoringBackup)
        return false
      }
      alert(
        (t.backupRestoredSuccess || 'Backup restaurado com sucesso! A página será recarregada.') +
          `\n\nChaves repostas: ${result.keysRestored}` +
          (result.serverOk ? '' : '\n(Aviso: confirme ligação ao servidor.)')
      )
      window.location.reload()
      return true
    } catch (error) {
      alert(t.errorRestoringBackup + ': ' + (error as Error).message)
      return false
    }
  }

  // Função para obter lista de backups automáticos
  const getAutoBackups = () => {
    try {
      const backupsStr = localStorage.getItem('nonato-auto-backups')
      if (!backupsStr) return []
      
      const backups = JSON.parse(backupsStr)
      return backups.sort((a: any, b: any) => b.timestamp - a.timestamp)
    } catch (e) {
      return []
    }
  }

  // Função para deletar backup automático
  const deleteAutoBackup = (timestamp: number) => {
    return deleteStoredBackupEntry(AUTO_BACKUP_STORAGE_KEY, timestamp)
  }

