  // Funções para gerenciar Serviços
  const servicoGrupoIdPadrao = () =>
    servicoGrupoSelecionadoId ||
    ordenarServicoGrupos(servicoGrupos)[0]?.id ||
    DEFAULT_SERVICO_GRUPO_ID

  const persistServicosEGrupos = async (nextServicos: typeof servicos, nextGrupos?: ServicoCadastroGrupo[]) => {
    const g = nextGrupos ?? servicoGrupos
    await saveData('nonato-servicos', nextServicos)
    await saveData('nonato-servicos-grupos', g)
  }

  const aplicarCadastroServicosCarregado = useCallback(
    (rawServicos: unknown, rawGrupos: unknown) => {
      let gruposInicial: ServicoCadastroGrupo[] = []
      if (Array.isArray(rawGrupos) && rawGrupos.length > 0) {
        gruposInicial = (rawGrupos as unknown[]).map((row, i) => {
          const g = row as { id?: unknown; nome?: unknown; ordem?: unknown }
          return {
            id: String(g.id ?? `servico-grupo-${i}`),
            nome: (typeof g.nome === 'string' ? g.nome.trim() : '') || 'Grupo',
            ordem: typeof g.ordem === 'number' && Number.isFinite(g.ordem) ? g.ordem : i,
          }
        })
      } else {
        gruposInicial = [{ id: DEFAULT_SERVICO_GRUPO_ID, nome: 'Geral', ordem: 0 }]
      }
      const idsGrupo = new Set(gruposInicial.map((g) => g.id))
      let servicosLista: typeof servicos = []
      if (Array.isArray(rawServicos)) {
        servicosLista = (rawServicos as typeof servicos).map((s) => {
          const { row } = migrarServicoLegacyCodNomeDesc(s)
          const gid =
            typeof row.grupoId === 'string' && idsGrupo.has(row.grupoId)
              ? row.grupoId
              : gruposInicial[0].id
          return {
            ...row,
            grupoId: gid,
            valor: normalizeServicoValorStored(row.valor),
          }
        }) as typeof servicos
      }
      setServicoGrupos(gruposInicial)
      setServicos(servicosLista)
      const primeiroG = ordenarServicoGrupos(gruposInicial)[0]?.id ?? null
      setServicoGrupoSelecionadoId(primeiroG)
      setServicoGrupoNomeEdicao(gruposInicial.find((g) => g.id === primeiroG)?.nome ?? '')
      setServicosActiveTab('listar')
      void saveData('nonato-servicos', servicosLista, true, true)
      void saveData('nonato-servicos-grupos', gruposInicial, true, true)
      return servicosLista.length
    },
    []
  )

  const restaurarCadastroServicosDoServidor = useCallback(async (): Promise<number> => {
    try {
      const res = await fetch('/api/data/restore-cadastro-servicos', {
        method: 'POST',
        cache: 'no-store',
      })
      const json = (await res.json()) as {
        success?: boolean
        message?: string
        servicos?: unknown
        grupos?: unknown
        count?: number
      }
      if (!res.ok || !json.success) {
        throw new Error(json.message || `Erro HTTP ${res.status}`)
      }
      const n = aplicarCadastroServicosCarregado(json.servicos, json.grupos)
      return n
    } catch (e) {
      const fromLoad = await loadData('nonato-servicos')
      const fromGrupos = await loadData('nonato-servicos-grupos')
      if (Array.isArray(fromLoad) && fromLoad.length > 0) {
        return aplicarCadastroServicosCarregado(fromLoad, fromGrupos)
      }
      throw e
    }
  }, [aplicarCadastroServicosCarregado])

  const handleAddServico = () => {
    setEditingServico(null)
    setServicoValorInput('')
    setServicoForm({
      cod: '',
      nome: '',
      descricao: '',
      valor: 0,
      grupoId: servicoGrupoIdPadrao(),
      tipoCobranca: 'unidade',
      categoria: 'servico'
    })
    setShowServicoForm(true)
  }

  /** Abre o formulário com HTT pré-preenchido no grupo selecionado (tarifas diferentes por grupo). */
  const handleQuickAddHttNoGrupo = (grupoIdOverride?: string) => {
    const gid = grupoIdOverride || servicoGrupoIdPadrao()
    const existente = servicos.find(
      (s) =>
        s.grupoId === gid &&
        (/^(HT|HTT)$/i.test(String(s.cod || '').trim()) ||
          /trabalh/i.test(`${s.nome || ''} ${s.descricao || ''}`.toLowerCase()))
    )
    if (existente) {
      handleEditServico(existente)
      return
    }
    setEditingServico(null)
    setServicoValorInput('')
    setServicoForm({
      cod: 'HTT',
      nome: 'Hora técnica trabalhada',
      descricao: 'HORA TECNICA TRABALHADA',
      valor: 0,
      grupoId: gid,
      tipoCobranca: 'hora',
      categoria: 'servico',
    })
    setShowServicoForm(true)
  }

  const handleEditServico = (servico: typeof servicos[0]) => {
    const valorN = normalizeServicoValorStored(servico.valor)
    setEditingServico({ ...servico, valor: valorN })
    setServicoValorInput(servicoValorToInputString(valorN))
    setServicoForm({
      cod: servico.cod || '',
      nome: servico.nome,
      descricao: servico.descricao || '',
      valor: valorN,
      grupoId: servico.grupoId || servicoGrupoIdPadrao(),
      tipoCobranca: servico.tipoCobranca,
      categoria: servico.categoria
    })
    setShowServicoForm(true)
  }

  const handleSaveServico = async () => {
    const valor = parseServicoValorInput(servicoValorInput)
    if (!servicoForm.nome.trim() || valor < 0 || Number.isNaN(valor)) {
      alert((t as any).preenchaNomeValor || 'Preencha o nome e um valor válido (zero ou maior) para o serviço!')
      return
    }

    createAutoBackupBeforeOperation()

    const idsG = new Set(servicoGrupos.map((g) => g.id))
    const grupoId =
      typeof servicoForm.grupoId === 'string' && idsG.has(servicoForm.grupoId)
        ? servicoForm.grupoId
        : (ordenarServicoGrupos(servicoGrupos)[0]?.id ?? DEFAULT_SERVICO_GRUPO_ID)

    let updatedServicos: typeof servicos
    let savedServico: typeof servicos[number]
    if (editingServico) {
      savedServico = {
        ...editingServico,
        grupoId,
        cod: servicoForm.cod || undefined,
        nome: servicoForm.nome,
        descricao: servicoForm.descricao || undefined,
        valor,
        tipoCobranca: servicoForm.tipoCobranca,
        categoria: servicoForm.categoria
      }
      updatedServicos = servicos.map(s =>
        s.id === editingServico.id
          ? savedServico
          : s
      )
    } else {
      const newServico = {
        id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
        grupoId,
        cod: servicoForm.cod || undefined,
        nome: servicoForm.nome,
        descricao: servicoForm.descricao || undefined,
        valor,
        tipoCobranca: servicoForm.tipoCobranca,
        categoria: servicoForm.categoria
      }
      savedServico = newServico
      updatedServicos = [...servicos, newServico]
    }
    setServicos(updatedServicos)

    try {
      await persistServicosEGrupos(updatedServicos)
    } catch (err) {
      console.error('Erro ao salvar serviços:', err)
      alert((t as any).erroAoSalvarServico || 'Não foi possível salvar. Verifique se o navegador permite armazenamento local (não use modo anônimo sem permissão) ou tente novamente.')
      return
    }

    setServicoForm({
      cod: savedServico.cod || '',
      nome: savedServico.nome,
      descricao: savedServico.descricao || '',
      valor: savedServico.valor,
      grupoId: savedServico.grupoId,
      tipoCobranca: savedServico.tipoCobranca,
      categoria: savedServico.categoria
    })
    setServicoValorInput(servicoValorToInputString(savedServico.valor))
    setEditingServico(savedServico)
    alert((t as any).servicoSalvo || 'Serviço salvo com sucesso!')
  }

  // Funções para Agenda
