  const handleEditAgendamento = (agendamento: Agendamento) => {
    setEditingAgendamento(agendamento)
    const resolved = resolveClienteEEquipamentoParaFormularioAgenda(agendamento, clientes)
    setAgendaForm({
      ...agendamento,
      ...resolved,
      tipo: normalizeTipoAgendamento(agendamento),
      status: normalizeStatusAgendamento(agendamento),
      categoria: normalizeCategoriaAgendamento(agendamento),
      subtipoPessoal: agendamento.subtipoPessoal || 'pessoal',
      assunto: agendamento.assunto || '',
    })
    const dias = agendamento.diasSelecionados?.length
      ? [...agendamento.diasSelecionados].sort()
      : []
    setAgendaDiasRascunho(dias)
    if (dias.length > 0) {
      const d = new Date(dias[0] + 'T12:00:00')
      setAgendaPickerMes(d.getMonth())
      setAgendaPickerAno(d.getFullYear())
    } else {
      const hoje = new Date()
      setAgendaPickerMes(hoje.getMonth())
      setAgendaPickerAno(hoje.getFullYear())
    }
    setShowAgendaForm(true)
  }

  const toggleAgendaListaSecao = useCallback((id: AgendaListaSecaoId) => {
    setAgendaListaSecoesAbertas((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const expandirTodasSecoesAgendaLista = useCallback(() => {
    setAgendaListaSecoesAbertas(new Set(AGENDA_LISTA_SECAO_IDS))
  }, [])

  const retrairTodasSecoesAgendaLista = useCallback(() => {
    setAgendaListaSecoesAbertas(new Set())
    setAgendaListaCardsExpandidos(new Set())
  }, [])

  const toggleAgendaListaCardExpandido = useCallback((id: string) => {
    setAgendaListaCardsExpandidos((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const handleSaveAgendamento = (): boolean => {
    const pessoal = isAgendamentoPessoal(agendaForm)
    if (!agendaForm.data || !agendaForm.hora) {
      alert(safeT?.fillAllFields || 'Preencha todos os campos obrigatórios!')
      return false
    }
    if (!pessoal && (!agendaForm.tecnico || !agendaForm.cliente)) {
      alert(safeT?.fillAllFields || 'Preencha todos os campos obrigatórios!')
      return false
    }

    const formSanitizado: Agendamento = {
      ...agendaForm,
      tipo: normalizeTipoAgendamento(agendaForm),
      status: normalizeStatusAgendamento(agendaForm),
      categoria: pessoal ? 'pessoal' : 'servico',
      subtipoPessoal: pessoal ? agendaForm.subtipoPessoal || 'pessoal' : undefined,
      assunto: pessoal ? String(agendaForm.assunto || '').trim() : undefined,
      ...(pessoal
        ? {
            tecnico: '',
            tipo: 'pre-agendamento',
            cliente: '',
            clienteId: '',
            equipamento: '',
            equipamentoId: '',
            telefone: '',
            endereco: '',
            cidade: '',
            necessidadePecas: false,
            codigoNotaFiscal: '',
            pecasAnexadas: [],
          }
        : {}),
    }

    if (!pessoal && formSanitizado.equipamentoId && !String(formSanitizado.equipamento || '').trim()) {
      const cliSave = clientes.find((c) => c.id === formSanitizado.clienteId)
      const eqSave = cliSave?.equipamentos?.find(
        (e) => e.numeroSerie === formSanitizado.equipamentoId || e.id === formSanitizado.equipamentoId
      )
      if (eqSave) {
        formSanitizado.equipamento = `${eqSave.modelo} (${eqSave.numeroSerie})`
      }
    }

    const statusAntes = editingAgendamento ? normalizeStatusAgendamento(editingAgendamento) : null
    const statusDepois = normalizeStatusAgendamento(formSanitizado)
    const marcarConclusao =
      statusDepois === 'concluido' && statusAntes !== 'concluido'
        ? { dataRegistoConclusao: new Date().toISOString() }
        : {}

    const savedAgendamento: Agendamento = editingAgendamento
      ? { ...formSanitizado, id: editingAgendamento.id, ...marcarConclusao }
      : {
          ...formSanitizado,
          id: Date.now().toString(),
          ...marcarConclusao,
        }

    if (editingAgendamento) {
      const updated = agendamentos.map((a) => (a.id === editingAgendamento.id ? savedAgendamento : a))
      setAgendamentos(updated)
      saveData('nonato-agendamentos', updated)
    } else {
      const newAgendamento: Agendamento = savedAgendamento
      const updated = [...agendamentos, newAgendamento]
      setAgendamentos(updated)
      saveData('nonato-agendamentos', updated)
    }
    setEditingAgendamento(savedAgendamento)
    setAgendaForm(savedAgendamento)
    setAgendaDiasRascunho(savedAgendamento.diasSelecionados?.length ? [...savedAgendamento.diasSelecionados].sort() : [])
    setUnsavedFormBaseline('agenda', savedAgendamento)
    alert(safeT?.saveSuccess || 'Agendamento salvo com sucesso!')
    return true
  }

  const handleDeleteAgendamento = (id: string) => {
    if (window.confirm(safeT?.confirmDelete || 'Tem certeza que deseja excluir este agendamento?')) {
      const updated = agendamentos.filter(a => a.id !== id)
      setAgendamentos(updated)
      saveData('nonato-agendamentos', updated)
    }
  }

  const toggleAgendaDiaRascunho = (dateKey: string) => {
    setAgendaDiasRascunho((prev) => {
      if (prev.includes(dateKey)) return prev.filter((d) => d !== dateKey)
      return [...prev, dateKey].sort()
    })
  }

  const confirmarAgendaDiasCalendario = () => {
    const sorted = [...agendaDiasRascunho].sort()
    if (sorted.length === 0) {
      alert(safeT?.agendaSelecioneUmDia || 'Selecione pelo menos um dia no calendário.')
      return
    }
    setAgendaForm((f) => ({
      ...f,
      duracaoEstimada: String(sorted.length),
      diasSelecionados: sorted,
    }))
  }

  const goAgendaPickerMes = (delta: number) => {
    const d = new Date(agendaPickerAno, agendaPickerMes + delta, 1)
    setAgendaPickerMes(d.getMonth())
    setAgendaPickerAno(d.getFullYear())
  }

  // Lembretes Agenda: agendamentos de hoje e amanhã (exclui cancelados)
  const getAgendamentosLembrete = (): Agendamento[] => {
    const today = new Date()
    const tomorrow = new Date(today)
    tomorrow.setDate(tomorrow.getDate() + 1)
    const todayStr = today.toISOString().split('T')[0]
    const tomorrowStr = tomorrow.toISOString().split('T')[0]
    return agendamentos.filter(
      (a) =>
        a.status !== 'cancelado' &&
        (a.data === todayStr || a.data === tomorrowStr)
    )
  }

  // Formatar telefone para WhatsApp (apenas dígitos; Portugal 351 se 9 dígitos)
  const formatTelefoneWhatsApp = (telefone: string): string => {
    const digits = (telefone || '').replace(/\D/g, '')
    if (digits.length === 9 && digits.startsWith('9')) return '351' + digits
    if (digits.length >= 9) return digits
    return '351' + digits
  }

  // Mensagem de lembrete para WhatsApp
  const getMensagemLembreteAgenda = (a: Agendamento): string => {
    const dataPt = a.data ? new Date(a.data + 'T12:00:00').toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }) : ''
    const tipoLabel = a.tipo === 'agendamento-tecnico' ? (safeT?.agendamentoTecnico || 'Agendamento Técnico') : (safeT?.preAgendamento || 'Pré-Agendamento')
    const titulo = rotuloTituloAgendamento(a, safeT as Record<string, string | undefined>)
    const pessoal = isAgendamentoPessoal(a)
    return [
      (safeT?.lembreteAgendaWhatsAppPrefixo || 'Lembrete Nonato Service:'),
      '',
      (safeT?.lembreteAgendaTemosAgendado || 'Temos agendado para') + ` ${dataPt} ${safeT?.as || 'às'} ${a.hora || ''}:`,
      pessoal ? `• ${titulo}` : `• ${tipoLabel}`,
      !pessoal ? `• ${safeT?.cliente || 'Cliente'}: ${a.cliente || ''}` : '',
      !pessoal && a.tecnico ? `• ${safeT?.tecnico || 'Técnico'}: ${a.tecnico}` : '',
      !pessoal && a.equipamento ? `• ${safeT?.equipamento || 'Equipamento'}: ${a.equipamento}` : '',
      '',
      (safeT?.lembreteAgendaQualquerDuvida || 'Qualquer dúvida, contacte-nos.')
    ].filter(Boolean).join('\n')
  }

  // Lembretes 3x por dia: 8h, 12h, 17h — ao abrir a app nesses horários mostra o modal uma vez por slot
  useEffect(() => {
    const REMINDER_SLOTS = [8, 12, 17]
    const check = () => {
      const now = new Date()
      const hour = now.getHours()
      const dateKey = now.toISOString().split('T')[0]
      if (!REMINDER_SLOTS.includes(hour)) return
      const key = `nonato-agenda-reminder-${dateKey}-${hour}`
      try {
        if (typeof window !== 'undefined' && localStorage.getItem(key)) return
      } catch (_) {}
      const list = getAgendamentosLembrete()
      if (list.length === 0) return
      setShowAgendaLembreteModal(true)
      try {
        if (typeof window !== 'undefined') localStorage.setItem(key, '1')
      } catch (_) {}
    }
    check()
    const interval = setInterval(check, 60000)
    return () => clearInterval(interval)
  }, [agendamentos])

