  /** Prioriza `relatoriosServico` (fonte de verdade); cópias em `cliente.relatorios` podem ficar desactualizadas (ex.: `diasTrabalho`). */
  const resolverRelatorioServicoDono = (relatorio: RelatorioServico): RelatorioServico => {
    if (!relatorio?.id) return relatorio
    const rid = String(relatorio.id)
    const globalHit = relatoriosServico.find((r) => r.id === rid)
    if (globalHit) return globalHit
    for (const c of clientes) {
      const map = c.relatorios as Record<string, RelatorioServico[]> | undefined
      if (!map || typeof map !== 'object') continue
      for (const equipKey of Object.keys(map)) {
        const arr = map[equipKey]
        if (!Array.isArray(arr)) continue
        const hit = arr.find((r) => r.id === rid)
        if (hit) return hit
      }
    }
    return relatorio
  }

  const handleEditRelatorioServico = (relatorio: RelatorioServico) => {
    const r = resolverRelatorioServicoDono(relatorio)
    const clienteResolvido = findClienteByRelatorio(clientes, r)
    const clienteId = resolverClienteIdRelatorio(r, clientes)
    setEditingRelatorioServico(r)
    setEditingDiaTrabalhoIndex(null)
    const equipamentosEditRaw = normalizarEquipamentosRelatorio(r)
    let equipamentosEdit = prepararEquipamentosRelatorioParaEdicao(
      equipamentosEditRaw,
      clienteResolvido?.equipamentos,
      equipamentos
    )
    if (equipamentosEdit.length === 0) {
      equipamentosEdit = [criarEquipamentoRelatorioVazio('cliente')]
    }
    let diasTrabalhoEdit = sortDiasTrabalhoCronologicamente(
      normalizarDiasTrabalhoParaPersist(r.diasTrabalho ? [...r.diasTrabalho] : [])
    )
    if (clienteResolvido) {
      const { kmIda, kmRetorno } = getKmPadraoDoCliente(clienteResolvido)
      if (kmIda || kmRetorno) {
        diasTrabalhoEdit = diasTrabalhoEdit.map((dia) =>
          atualizarCalculosDia({
            ...dia,
            kmIda: kmIda || dia.kmIda,
            kmRetorno: kmRetorno || dia.kmRetorno,
          })
        )
      }
    }
    const totaisKmEdit = calcularTotais(diasTrabalhoEdit)
    setRelatorioServicoForm({
      ...r,
      clienteId,
      cliente: r.cliente || clienteResolvido?.nomeEmpresa || '',
      cidade:
        r.cidade ||
        clienteResolvido?.conselho ||
        clienteResolvido?.localidade ||
        '',
      telefone: r.telefone || clienteResolvido?.telefones || '',
      ...sincronizarCamposLegadoEquipamentos(equipamentosEdit, equipamentos),
      equipamentoOrigem: r.equipamentoOrigem === 'armazem' ? 'armazem' : 'cliente',
      diasTrabalho: diasTrabalhoEdit,
      kmsPercorridos: totaisKmEdit.kmsPercorridos,
      pecasSubstituicao: r.pecasSubstituicao ? [...r.pecasSubstituicao] : [],
      pecasInstaladas: r.pecasInstaladas ? [...r.pecasInstaladas] : [],
      pecasInstaladasSubstituidas: r.pecasInstaladasSubstituidas ?? (r.pecasInstaladas?.length ?? 0) > 0,
    })
    if (clienteResolvido) {
      const { kmIda, kmRetorno } = getKmPadraoDoCliente(clienteResolvido)
      if (kmIda || kmRetorno) {
        setNovoDiaTrabalho((prev) => {
          const next = atualizarCalculosDia({
            ...prev,
            data: prev.data || new Date().toISOString().split('T')[0],
            kmIda: kmIda || prev.kmIda,
            kmRetorno: kmRetorno || prev.kmRetorno,
          })
          return next
        })
      }
    }
    setShowRelatorioServicoForm(true)
    scrollRelatorioServicoFormIntoView()
  }
  editRelatorioServicoRef.current = handleEditRelatorioServico

