  const handlePasteImagemPecaBiblioteca = useCallback(
    (e: React.ClipboardEvent | ClipboardEvent) => {
      const cd = e.clipboardData
      if (!cd) return

      const htmlEarly = cd.getData('text/html') || ''
      const plainEarly = cd.getData('text/plain') || ''
      if (clipboardLooksLikeCatalogImport(htmlEarly, plainEarly)) return

      const aplicarFileImagem = (file: File) => {
        const reader = new FileReader()
        reader.onload = () => {
          setPecaBibliotecaForm(prev => ({ ...prev, imagem: reader.result as string }))
        }
        reader.readAsDataURL(file)
      }

      const pareceImagem = (file: File) => {
        if (file.type && file.type.startsWith('image/')) return true
        if (!file.type && file.size > 0) {
          const n = (file.name || '').toLowerCase()
          return /\.(png|jpe?g|gif|webp|bmp|svg|ico)$/.test(n)
        }
        return false
      }

      const items = cd.items
      if (items && items.length > 0) {
        for (let i = 0; i < items.length; i++) {
          const it = items[i]
          if (it.kind === 'file') {
            const file = it.getAsFile()
            if (file && file.size > 0 && (it.type.startsWith('image/') || pareceImagem(file))) {
              e.preventDefault()
              e.stopPropagation()
              aplicarFileImagem(file)
              return
            }
          }
        }
      }

      if (cd.files && cd.files.length > 0) {
        for (let i = 0; i < cd.files.length; i++) {
          const f = cd.files[i]
          if (f.size > 0 && (f.type.startsWith('image/') || pareceImagem(f))) {
            e.preventDefault()
            e.stopPropagation()
            aplicarFileImagem(f)
            return
          }
        }
      }

      const html = cd.getData('text/html')
      if (html && /<img/i.test(html)) {
        try {
          const doc = new DOMParser().parseFromString(html, 'text/html')
          const src = doc.querySelector('img')?.getAttribute('src')?.trim()
          if (src && (src.startsWith('data:image') || /^https?:\/\//i.test(src))) {
            e.preventDefault()
            e.stopPropagation()
            void aplicarImagemPecaBibliotecaDeUrl(src)
            return
          }
        } catch {
          /* ignorar */
        }
      }

      const uriList = cd.getData('text/uri-list')?.trim()
      if (uriList) {
        const primeira = uriList.split(/\r?\n/).find((u) => u.trim().length > 0)?.trim() ?? ''
        if (/^https?:\/\//i.test(primeira)) {
          e.preventDefault()
          e.stopPropagation()
          void aplicarImagemPecaBibliotecaDeUrl(primeira)
          return
        }
      }

      const text = cd.getData('text/plain')?.trim() ?? ''
      if (/^https?:\/\//i.test(text) || text.startsWith('data:image')) {
        e.preventDefault()
        e.stopPropagation()
        void aplicarImagemPecaBibliotecaDeUrl(text)
      }
    },
    [aplicarImagemPecaBibliotecaDeUrl]
  )

  const showBibliotecaImgPreview = useCallback((e: React.MouseEvent, src: string, alt: string) => {
    if (typeof window === 'undefined') return
    const trimmedSrc = String(src || '').trim()
    if (!trimmedSrc || trimmedSrc === PECA_BIBLIOTECA_IMAGEM_PADRAO_SRC) return

    if (bibliotecaPreviewHideTimerRef.current) {
      clearTimeout(bibliotecaPreviewHideTimerRef.current)
      bibliotecaPreviewHideTimerRef.current = null
    }

    const seq = ++bibliotecaPreviewSeqRef.current
    const el = e.currentTarget as HTMLElement
    const r = el.getBoundingClientRect()
    const pad = 12
    const panelW = 328
    const panelH = 380
    let left = r.right + pad
    if (left + panelW > window.innerWidth - pad) {
      left = r.left - panelW - pad
    }
    if (left < pad) left = pad
    let top = r.top + (r.height - panelH) / 2
    if (top + panelH > window.innerHeight - pad) top = window.innerHeight - panelH - pad
    if (top < pad) top = pad
    setBibliotecaImageHoverPreview({ src: trimmedSrc, alt, left, top, seq, imageReady: false })
  }, [])
  const hideBibliotecaImgPreview = useCallback(() => {
    if (bibliotecaPreviewHideTimerRef.current) {
      clearTimeout(bibliotecaPreviewHideTimerRef.current)
    }
    bibliotecaPreviewHideTimerRef.current = setTimeout(() => {
      bibliotecaPreviewHideTimerRef.current = null
      setBibliotecaImageHoverPreview(null)
    }, 120)
  }, [])

  useEffect(() => {
    if (bibliotecaPreviewHideTimerRef.current) {
      clearTimeout(bibliotecaPreviewHideTimerRef.current)
      bibliotecaPreviewHideTimerRef.current = null
    }
    setBibliotecaImageHoverPreview(null)
  }, [abaBibliotecaPecas, activeTabId])

  useEffect(() => {
    return () => {
      if (bibliotecaPreviewHideTimerRef.current) {
        clearTimeout(bibliotecaPreviewHideTimerRef.current)
      }
    }
  }, [])

  /** Imagens em cache podem não disparar onLoad — marcar prontas sem ref (evita loop React #185). */
  useEffect(() => {
    const preview = bibliotecaImageHoverPreview
    if (!preview || preview.imageReady) return
    const { src, seq } = preview
    let cancelled = false
    const markReady = () => {
      if (cancelled) return
      setBibliotecaImageHoverPreview((prev) =>
        prev && prev.seq === seq && !prev.imageReady ? { ...prev, imageReady: true } : prev
      )
    }
    const img = new Image()
    img.onload = markReady
    img.onerror = () => {
      if (!cancelled) hideBibliotecaImgPreview()
    }
    img.src = src
    if (img.complete && img.naturalWidth > 0) markReady()
    return () => {
      cancelled = true
      img.onload = null
      img.onerror = null
    }
  }, [bibliotecaImageHoverPreview?.seq, bibliotecaImageHoverPreview?.src, hideBibliotecaImgPreview])

  function normalizeImportKey(v: any): string {
    return String(v ?? '').trim().toLowerCase().replace(/\s+/g, ' ')
  }

  /** Variantes do código para detetar duplicados (hífen, R prefixo/sufixo, zeros à esquerda). */
  function variantesCodigoPecaBiblioteca(codigo: string | undefined | null): string[] {
    const norm = normalizeImportKey(codigo)
    const out = new Set<string>(variantesCodigoHomagParaMatch(codigo))
    if (norm) out.add(norm)
    const compact = norm.replace(/[^a-z0-9]/g, '')
    if (compact && compact !== norm && compact.length >= 3) {
      out.add(compact)
    }
    if (/^\d+$/.test(compact) && compact.length >= 5) {
      const semZeros = compact.replace(/^0+/, '') || compact
      if (semZeros !== compact) out.add(semZeros)
    }
    return [...out]
  }

  function indiceVariantesPecaBiblioteca(p: PecaBiblioteca): string[] {
    const out = new Set<string>()
    for (const v of variantesCodigoPecaBiblioteca(p.codigo)) out.add(v)
    for (const c of [...(p.codigosAlternativos || []), ...(p.codigosAntigos || [])]) {
      for (const v of variantesCodigoPecaBiblioteca(c)) out.add(v)
    }
    for (const r of [...(p.referenciasAlternativas || []), ...(p.referenciasAntigas || [])]) {
      for (const v of variantesCodigoPecaBiblioteca(r)) out.add(v)
    }
    return [...out]
  }

  function pecaBibliotecaEstaNoCatalogo(p: PecaBiblioteca): boolean {
    return !ehImportacaoPendenteStrict(p)
  }

  function construirIndiceCodigosBiblioteca(biblioteca: PecaBiblioteca[]): Set<string> {
    const idx = new Set<string>()
    for (const p of biblioteca) {
      for (const v of indiceVariantesPecaBiblioteca(p)) idx.add(v)
    }
    return idx
  }

  function codigoExisteNaBibliotecaPecas(
    codigo: string | undefined | null,
    biblioteca: PecaBiblioteca[],
    excluirId?: string
  ): boolean {
    const alvo = variantesCodigoPecaBiblioteca(codigo)
    if (alvo.length === 0) return false
    return biblioteca.some((p) => {
      if (excluirId && p.id === excluirId) return false
      const existentes = indiceVariantesPecaBiblioteca(p)
      return existentes.some((v) => alvo.includes(v))
    })
  }

  const chavePecaBibliotecaParaImport = (p: { codigo?: string; nome?: string }) =>
    normalizeImportKey(p.codigo) || `n:${normalizeImportKey(p.nome)}`

  const codigoNormalizadoImport = (codigo: string | undefined | null) => normalizeImportKey(codigo)

  const separarPecasImportacao = useCallback(
    (pecas: PecaBiblioteca[]) => {
      const catalogo = pecasBiblioteca.filter(pecaBibliotecaEstaNoCatalogo)
      const filaPendente = pecasBiblioteca.filter((p) => ehImportacaoPendenteStrict(p))
      const indiceCatalogo = construirIndiceCodigosBiblioteca(catalogo)
      const indiceFila = construirIndiceCodigosBiblioteca(filaPendente)
      const novas: PecaBiblioteca[] = []
      const duplicadasCatalogo: PecaBiblioteca[] = []
      const duplicadasFila: PecaBiblioteca[] = []
      const duplicadasLote: PecaBiblioteca[] = []
      const semCodigo: PecaBiblioteca[] = []
      const vistoCodigoLote = new Set<string>()

      for (const p of pecas) {
        const codigo = String(p.codigo ?? '').trim()
        if (!codigo) {
          semCodigo.push(p)
          continue
        }
        const variantes = variantesCodigoPecaBiblioteca(codigo)
        if (variantes.length === 0) {
          semCodigo.push(p)
          continue
        }
        if (variantes.some((v) => indiceCatalogo.has(v))) {
          duplicadasCatalogo.push(p)
          continue
        }
        if (variantes.some((v) => indiceFila.has(v))) {
          duplicadasFila.push(p)
          continue
        }
        if (variantes.some((v) => vistoCodigoLote.has(v))) {
          duplicadasLote.push(p)
          continue
        }
        variantes.forEach((v) => vistoCodigoLote.add(v))
        novas.push(p)
      }

      const duplicadas = [...duplicadasCatalogo, ...duplicadasFila, ...duplicadasLote]
      return { novas, duplicadas, duplicadasCatalogo, duplicadasFila, duplicadasLote, semCodigo }
    },
    [pecasBiblioteca]
  )

  const montarMensagemImportacaoIgnoradas = useCallback(
    (info: {
      duplicadasCatalogo: PecaBiblioteca[]
      duplicadasFila: PecaBiblioteca[]
      duplicadasLote: PecaBiblioteca[]
      semCodigo: PecaBiblioteca[]
    }) => {
      const partes: string[] = []
      if (info.duplicadasCatalogo.length > 0) {
        partes.push(
          String(
            (t as any)?.importacaoDuplicadasCatalogo ??
              '{count} peça(s) já existem no catálogo da biblioteca (gravadas).'
          ).replace('{count}', String(info.duplicadasCatalogo.length))
        )
      }
      if (info.duplicadasFila.length > 0) {
        partes.push(
          String(
            (t as any)?.importacaoDuplicadasFila ??
              '{count} peça(s) já estão na fila amarela (importação pendente) — não foram duplicadas.'
          ).replace('{count}', String(info.duplicadasFila.length))
        )
      }
      if (info.duplicadasLote.length > 0) {
        partes.push(
          String(
            (t as any)?.importacaoDuplicadasLote ??
              '{count} peça(s) repetidas na mesma colagem/importação.'
          ).replace('{count}', String(info.duplicadasLote.length))
        )
      }
      if (info.semCodigo.length > 0) {
        partes.push(
          String(
            (t as any)?.importacaoSemCodigoIgnoradas ??
              '{count} linha(s) ignorada(s) por não ter código identificável.'
          ).replace('{count}', String(info.semCodigo.length))
        )
      }
      return partes.join('\n')
    },
    [t]
  )

  const listarCodigosPecasImport = (pecas: PecaBiblioteca[], max = 12) =>
    [...new Set(pecas.map((p) => String(p.codigo || '').trim()).filter(Boolean))].slice(0, max).join(', ')

  const processarDuplicadosImportacao = useCallback(
    (pecas: PecaBiblioteca[], opts?: { notificar?: boolean }) => {
      const notificar = opts?.notificar === true
      const { novas, duplicadas, duplicadasCatalogo, duplicadasFila, duplicadasLote, semCodigo } =
        separarPecasImportacao(pecas)
      setImportacaoDuplicadasIgnoradas(duplicadas.length + semCodigo.length)
      setImportacaoAnaliseColagem({
        totalColagem: pecas.length,
        novas,
        duplicadasCatalogo,
        duplicadasFila,
        duplicadasLote,
        semCodigo,
      })

      const detalheIgnoradas = montarMensagemImportacaoIgnoradas({
        duplicadasCatalogo,
        duplicadasFila,
        duplicadasLote,
        semCodigo,
      })

      if (novas.length === 0) {
        setImportacaoPreview(null)
        const msgBase =
          duplicadasCatalogo.length > 0
            ? String(
                (t as any)?.importacaoPreviewTodasDuplicadas ??
                  'De {total} peça(s) colada(s), {count} já existem no catálogo da biblioteca — nenhuma nova para importar.'
              )
                .replace('{total}', String(pecas.length))
                .replace('{count}', String(duplicadasCatalogo.length))
            : duplicadasFila.length > 0
              ? String(
                  (t as any)?.importacaoPreviewTodasNaFila ??
                    'De {total} peça(s), {count} já estão na fila amarela (pendentes). Nenhuma peça nova.'
                )
                  .replace('{total}', String(pecas.length))
                  .replace('{count}', String(duplicadasFila.length))
              : String(
                  (t as any)?.importacaoPreviewNenhumaNova ??
                    'Nenhuma peça nova para importar após filtrar duplicados e linhas inválidas.'
                )
        const msg = detalheIgnoradas ? `${msgBase}\n\n${detalheIgnoradas}` : msgBase
        setImportacaoUrlError(msgBase)
        if (notificar) {
          const codes = listarCodigosPecasImport(
            duplicadasCatalogo.length
              ? duplicadasCatalogo
              : duplicadasFila.length
                ? duplicadasFila
                : duplicadas.length
                  ? duplicadas
                  : semCodigo
          )
          alert(
            codes
              ? `${msg}\n\n${(t as any)?.importacaoCodigosDuplicadosLista || 'Códigos:'} ${codes}`
              : msg
          )
        }
        return {
          ok: false as const,
          novas: [] as PecaBiblioteca[],
          duplicadas,
          duplicadasCatalogo,
          duplicadasFila,
        }
      }

      if ((duplicadas.length > 0 || semCodigo.length > 0) && notificar) {
        const msg = String(
          (t as any)?.importacaoParcialDuplicadas ??
            'De {total} peça(s) colada(s): {novas} nova(s) para importar, {ignoradas} já existente(s) ou ignorada(s).'
        )
          .replace('{total}', String(pecas.length))
          .replace('{novas}', String(novas.length))
          .replace('{ignoradas}', String(duplicadas.length + semCodigo.length))
        const codes = listarCodigosPecasImport([...duplicadasCatalogo, ...duplicadasFila, ...duplicadasLote])
        const detectadosHomag = countHomagCodesInText(importacaoTextoColado)
        const homagHint =
          detectadosHomag >= 3 && detectadosHomag > pecas.length
            ? String(
                (t as any)?.importacaoHomagCodigosNaPagina ??
                  'A página colada contém cerca de {detectados} código(s) HOMAG; o sistema reconheceu {reconhecidas} peça(s).'
              )
                .replace('{detectados}', String(detectadosHomag))
                .replace('{reconhecidas}', String(pecas.length))
            : ''
        const dupHint =
          duplicadasCatalogo.length > 0
            ? String(
                (t as any)?.importacaoHomagDuplicadasExplicacao ??
                  'Peças «ignoradas» porque o código já existe no catálogo ou na fila amarela — não é falha de cópia.'
              )
            : ''
        alert(
          `${msg}${detalheIgnoradas ? `\n\n${detalheIgnoradas}` : ''}${
            homagHint ? `\n\n${homagHint}` : ''
          }${dupHint ? `\n\n${dupHint}` : ''}${
            codes
              ? `\n\n${(t as any)?.importacaoCodigosIgnorados || 'Códigos ignorados:'} ${codes}`
              : ''
          }`
        )
      }

      const catalogo = pecasBiblioteca.filter(pecaBibliotecaEstaNoCatalogo)
      const novasComNumero = atribuirNumerosSequenciaNovasPecas(novas, pecasBiblioteca, categoriasPecas).filter(
        (p) => !codigoExisteNaBibliotecaPecas(p.codigo, catalogo)
      )
      if (novasComNumero.length === 0) {
        setImportacaoPreview(null)
        const msgBase =
          duplicadasCatalogo.length > 0
            ? String(
                (t as any)?.importacaoPreviewTodasDuplicadas ??
                  'De {total} peça(s) colada(s), {count} já existem no catálogo da biblioteca — nenhuma nova para importar.'
              )
                .replace('{total}', String(pecas.length))
                .replace('{count}', String(duplicadasCatalogo.length))
            : duplicadasFila.length > 0
              ? String(
                  (t as any)?.importacaoPreviewTodasNaFila ??
                    'De {total} peça(s), {count} já estão na fila amarela (pendentes).'
                )
                  .replace('{total}', String(pecas.length))
                  .replace('{count}', String(duplicadasFila.length))
              : String(
                  (t as any)?.importacaoPreviewNenhumaNova ??
                    'Nenhuma peça nova para importar após filtrar duplicados e linhas inválidas.'
                )
        setImportacaoUrlError(msgBase)
        if (notificar) alert(detalheIgnoradas ? `${msgBase}\n\n${detalheIgnoradas}` : msgBase)
        return {
          ok: false as const,
          novas: [] as PecaBiblioteca[],
          duplicadas,
          duplicadasCatalogo,
          duplicadasFila,
        }
      }
      setImportacaoPreview(novasComNumero)
      setImportacaoUrlError(null)
      return { ok: true as const, novas: novasComNumero, duplicadas, duplicadasCatalogo, duplicadasFila }
    },
    [separarPecasImportacao, montarMensagemImportacaoIgnoradas, t, pecasBiblioteca, categoriasPecas, importacaoTextoColado]
  )

  const aplicarPreviewImportacaoFiltrado = useCallback(
    (pecas: PecaBiblioteca[], opts?: { notificar?: boolean }): boolean =>
      processarDuplicadosImportacao(pecas, opts).ok,
    [processarDuplicadosImportacao]
  )

  function buildImportedPecaDescricao(nome: string, codigo: string, descricaoOriginal: string): string {
    const nomeLimpo = String(nome || '').trim()
    const codigoLimpo = String(codigo || '').trim()
    const descricaoLimpa = String(descricaoOriginal || '').trim()

    const partesBase = [nomeLimpo, codigoLimpo ? `COD: ${codigoLimpo}` : ''].filter(Boolean)
    const base = partesBase.join(' | ').trim()

    if (!descricaoLimpa) return base || nomeLimpo || codigoLimpo

    const descricaoNorm = normalizeImportKey(descricaoLimpa)
    const nomeNorm = normalizeImportKey(nomeLimpo)
    const codigoNorm = normalizeImportKey(codigoLimpo)
    const temNome = !!nomeNorm && descricaoNorm.includes(nomeNorm)
    const temCodigo = !!codigoNorm && descricaoNorm.includes(codigoNorm)

    if (temNome && temCodigo) return descricaoLimpa
    if (base) return `${base} | ${descricaoLimpa}`
    return descricaoLimpa
  }

  // Mapeia objeto genérico (JSON do site) para PecaBiblioteca
  function mapItemToPecaBiblioteca(item: any, index: number): PecaBiblioteca {
    const codigo = String(item?.codigo ?? item?.code ?? item?.partNumber ?? item?.sku ?? item?.numero ?? item?.id ?? item?.ref ?? '').trim()
    let nome = String(item?.nome ?? item?.name ?? '').trim()
    const descricao = String(item?.descricao ?? item?.description ?? item?.designation ?? '').trim()
    if (!nome) {
      nome = descricao
        ? descricao.length > 220
          ? `${descricao.slice(0, 220)}…`
          : descricao
        : codigo || `Peça ${index + 1}`
    }
    const preco = item?.preco != null ? String(item.preco) : (item?.price != null ? String(item.price) : (item?.precoUnitario != null ? String(item.precoUnitario) : ''))
    let imagem = String(
      item?.imagem ??
        item?.image ??
        item?.img ??
        item?.imagem_url ??
        item?.imageUrl ??
        item?.photo ??
        item?.urlImagem ??
        item?.thumbnail ??
        item?.thumb ??
        item?.thumbnailUrl ??
        item?.picture ??
        item?.mainImage ??
        item?.main_image ??
        item?.image_link ??
        item?.imageLink ??
        item?.mediaUrl ??
        item?.url_image ??
        item?.image_url ??
        item?.foto ??
        item?.featuredImage ??
        item?.featured_image ??
        item?.smallImage ??
        item?.largeImage ??
        item?.imagePath ??
        item?.image_path ??
        ''
    ).trim()
    if (!imagem) {
      const maybeImgUrl = String(item?.url ?? item?.link ?? item?.href ?? '').trim()
      if (/\.(jpg|jpeg|png|webp|gif|svg)(\?|#|$)/i.test(maybeImgUrl)) imagem = maybeImgUrl
    }
    // Catálogos JSON: images/gallery como array de URLs ou objetos { url, src, ... }
    if (!imagem) {
      const arr =
        item?.images ??
        item?.photos ??
        item?.gallery ??
        item?.medias ??
        item?.pictures ??
        item?.media
      if (Array.isArray(arr) && arr.length > 0) {
        const x = arr[0]
        if (typeof x === 'string' && x.trim()) imagem = x.trim()
        else if (x && typeof x === 'object') {
          imagem = String(
            (x as any).url ??
              (x as any).src ??
              (x as any).image ??
              (x as any).href ??
              (x as any).large ??
              (x as any).full ??
              (x as any).original ??
              (x as any).path ??
              (x as any).uri ??
              ''
          ).trim()
        }
      }
    }
    if (!imagem && item?.media && typeof item.media === 'object' && !Array.isArray(item.media)) {
      const m = item.media as Record<string, unknown>
      const u = m.url ?? m.src ?? m.image ?? m.href
      if (typeof u === 'string' && u.trim()) imagem = u.trim()
    }
    // CSV/campos arbitrários: cabeçalhos como "URL da imagem", "Image URL", "Photo link"
    if (!imagem && item && typeof item === 'object') {
      for (const [k, v] of Object.entries(item)) {
        if (typeof v !== 'string' || !v.trim()) continue
        const kn = k.toLowerCase()
        if (!/(imagem|image|photo|foto|miniatura|thumb|picture|capa|poster|banner|galeria|gallery)/i.test(kn)) continue
        const s = v.trim().replace(/&amp;/g, '&')
        if (/^https?:\/\//i.test(s) || s.startsWith('//') || /\.(jpg|jpeg|png|webp|gif|svg)(\?|#|$)/i.test(s)) {
          imagem = s.startsWith('//') ? `https:${s}` : s
          break
        }
      }
    }
    if (imagem.startsWith('//')) imagem = `https:${imagem}`

    const refsAlt = new Set<string>(
      [...(item?.referenciasAlternativas || []), ...(item?.referenciasAntigas || [])]
        .map((r: unknown) => String(r ?? '').trim())
        .filter(Boolean)
    )
    const codsAlt = new Set<string>(
      [...(item?.codigosAlternativos || []), ...(item?.codigosAntigos || [])]
        .map((c: unknown) => String(c ?? '').trim())
        .filter(Boolean)
    )
    if (codigo) {
      const ref = referenciaHomagDeTexto(codigo)
      if (ref) refsAlt.add(ref)
      const nucleo = nucleoCodigoHomag(codigo)
      if (nucleo) codsAlt.add(nucleo)
      for (const v of variantesCodigoHomagParaMatch(codigo)) {
        if (/^r?\d{7,11}r?$/i.test(v.replace(/[^a-z0-9]/g, ''))) codsAlt.add(v)
        const r = referenciaHomagDeTexto(v)
        if (r) refsAlt.add(r)
      }
    }
    const codigoNorm = compactPecaCodigo(codigo)
    const referenciasAlternativas = [...refsAlt].filter((r) => compactPecaCodigo(r) !== codigoNorm && r !== codigo)
    const codigosAlternativos = [...codsAlt].filter((c) => compactPecaCodigo(c) !== codigoNorm)

    return {
      id: item?.id && typeof item.id === 'string' ? item.id : `import-${Date.now()}-${index}-${Math.random().toString(36).slice(2, 9)}`,
      nome: nome || codigo || `Peça ${index + 1}`,
      codigo: codigo || `IMP-${index + 1}`,
      preco: preco || '',
      descricao: buildImportedPecaDescricao(nome || codigo || `Peça ${index + 1}`, codigo || `IMP-${index + 1}`, descricao || nome),
      categoria: item?.categoria ?? item?.category ?? item?.grupo ?? '',
      categoriaId: item?.categoriaId ?? item?.categoryId ?? '',
      subcategoria: item?.subcategoria ?? item?.subcategory ?? '',
      subcategoriaId: item?.subcategoriaId ?? item?.subcategoryId ?? '',
      importacaoPendente: Boolean(item?.importacaoPendente),
      imagem,
      ...(referenciasAlternativas.length ? { referenciasAlternativas } : {}),
      ...(codigosAlternativos.length ? { codigosAlternativos } : {}),
      dataCriacao: new Date().toISOString()
    }
  }

  const parseRawToPecas = useCallback((raw: string, lojaBaseUrl = '', pageUrl = ''): PecaBiblioteca[] => {
    const trimRaw = raw.trim()
    const lojaOrigin = (() => {
      const s = String(lojaBaseUrl || '').trim()
      if (!s) return ''
      try {
        const u = new URL(s.includes('://') ? s : `https://${s}`)
        if (u.protocol !== 'http:' && u.protocol !== 'https:') return ''
        return u.origin
      } catch {
        return ''
      }
    })()
    /** URL da página de onde veio o HTML (lista no «Buscar da URL» ou URL base ao colar) — resolve src relativos. */
    const pageBaseHref = (() => {
      const s = String(pageUrl || '').trim()
      if (!s) return ''
      try {
        const u = new URL(s.includes('://') ? s : `https://${s}`)
        if (u.protocol !== 'http:' && u.protocol !== 'https:') return ''
        return u.href
      } catch {
        return ''
      }
    })()
    let itens: any[] = []
    const pushIfValid = (obj: any) => {
      if (!obj || typeof obj !== 'object') return
      const maybeCodigo = String(obj?.codigo ?? obj?.code ?? obj?.partNumber ?? obj?.part_no ?? obj?.articleNumber ?? obj?.numero ?? obj?.id ?? obj?.ref ?? '').trim()
      const maybeNome = String(obj?.nome ?? obj?.name ?? obj?.descricao ?? obj?.description ?? obj?.designation ?? obj?.title ?? '').trim()
      if (maybeCodigo || maybeNome) itens.push(obj)
    }
    const csvSplit = (line: string, sep: string): string[] => {
      const out: string[] = []
      let cur = ''
      let quoted = false
      for (let i = 0; i < line.length; i++) {
        const ch = line[i]
        if (ch === '"') {
          if (quoted && line[i + 1] === '"') {
            cur += '"'
            i++
          } else {
            quoted = !quoted
          }
        } else if (ch === sep && !quoted) {
          out.push(cur)
          cur = ''
        } else {
          cur += ch
        }
      }
      out.push(cur)
      return out.map(v => v.trim())
    }

    const decodeHtmlUrl = (u: string) =>
      u.trim().replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#38;/g, '&')

    const extractBackgroundImageFromStyle = (styleVal: string): string => {
      if (!styleVal) return ''
      const m = styleVal.match(/background-image\s*:\s*url\(\s*["']?([^"')]+)["']?\s*\)/i)
      if (!m?.[1]) return ''
      const u = decodeHtmlUrl(m[1])
      if (u.startsWith('data:') || u.startsWith('blob:')) return ''
      return u
    }

    /** Extrai URL de imagem: img (lazy-load), picture, background CSS, link para .jpg, etc. */
    const extractImgSrcFromNode = (root: Element | null): string => {
      if (!root || typeof (root as Element).querySelector !== 'function') return ''

      const styleAttr = (root as HTMLElement).getAttribute('style') || ''
      const bgRoot = extractBackgroundImageFromStyle(styleAttr)
      if (bgRoot) return bgRoot.startsWith('//') ? `https:${bgRoot}` : bgRoot

      const pic = root.querySelector('picture source[srcset], picture source[src]') as HTMLSourceElement | null
      if (pic) {
        const ss = pic.getAttribute('srcset') || pic.getAttribute('src') || ''
        const first = ss.split(',')[0]?.trim().split(/\s+/)[0]
        if (first && !first.startsWith('data:') && !first.startsWith('blob:')) {
          const d = decodeHtmlUrl(first)
          return d.startsWith('//') ? `https:${d}` : d
        }
      }

      const link = root.querySelector(
        'a[href*=".jpg" i],a[href*=".jpeg" i],a[href*=".png" i],a[href*=".webp" i],a[href*=".gif" i],a[href*=".svg" i]'
      ) as HTMLAnchorElement | null
      if (link?.href && !link.href.startsWith('data:') && !link.href.startsWith('blob:')) return link.href

      const img = root.querySelector('img') as HTMLImageElement | null
      if (img) {
        const attrs = [
          'src',
          'data-src',
          'data-lazy-src',
          'data-original',
          'data-url',
          'data-image',
          'data-image-url',
          'data-lazy',
          'data-zoom-image',
          'data-large_image_url',
          'data-full-src',
          'data-img',
          'data-full-url',
          'data-href',
          'data-photosrc',
          'data-aura-rendered-src',
        ]
        for (const attr of attrs) {
          const v = img.getAttribute(attr)
          if (v && v.trim() && !v.startsWith('data:') && !v.startsWith('blob:')) {
            let decoded = decodeHtmlUrl(v)
            if (decoded.startsWith('//')) return `https:${decoded}`
            return decoded
          }
        }
        const lazySrcset = img.getAttribute('data-lazy-srcset') || img.getAttribute('data-srcset')
        const srcset = img.getAttribute('srcset') || lazySrcset
        if (srcset) {
          const candidates = srcset.split(',').map((p) => p.trim().split(/\s+/)[0]).filter(Boolean)
          for (const first of candidates) {
            if (first && !first.startsWith('data:') && !first.startsWith('blob:')) {
              const decoded = decodeHtmlUrl(first)
              return decoded.startsWith('//') ? `https:${decoded}` : decoded
            }
          }
        }
      }

      const bgNode = root.querySelector('[style*="background"]')
      if (bgNode) {
        const s = (bgNode as HTMLElement).getAttribute('style') || ''
        const u = extractBackgroundImageFromStyle(s)
        if (u) return u.startsWith('//') ? `https:${u}` : u
      }

      return ''
    }

    const looksLikeHtml =
      trimRaw.startsWith('<') ||
      /<table\b/i.test(trimRaw) ||
      /<img\b[^>]*\bsrc\s*=/i.test(trimRaw)

    if (looksLikeHtml) {
      // Suporte a importação a partir de páginas HTML (tabelas/listas + JSON embutido em scripts)
      try {
        const parser = new DOMParser()
        const doc = parser.parseFromString(raw, 'text/html')
        const baseHref = (doc.querySelector('base[href]') as HTMLBaseElement | null)?.href || ''
        const documentBase = baseHref || pageBaseHref || (lojaOrigin ? `${lojaOrigin}/` : '')

        const resolveUrl = (u: string): string => {
          if (!u) return ''
          const t = u.trim().replace(/&amp;/g, '&')
          if (!t || t.startsWith('data:') || t.startsWith('blob:')) return t
          try {
            if (t.startsWith('//')) return `https:${t}`
            if (documentBase) return new URL(t, documentBase).href
            if (t.startsWith('/') && lojaOrigin) return new URL(t, `${lojaOrigin}/`).href
            return t
          } catch {
            return t
          }
        }

        const isJunkImgUrl = (src: string): boolean => {
          const s = src.toLowerCase()
          if (!s || s.length < 10) return true
          if (/spacer|blank\.|clear\.gif|pixel\.|1x1|transparent|placeholder|loading\.svg|s\.gif|w\.gif/i.test(s)) return true
          return false
        }
        const firstValidImgInRow = (row: Element): string => {
          for (const node of row.querySelectorAll('img')) {
            const s = extractImgSrcFromNode(node)
            if (s && !isJunkImgUrl(s)) return s
          }
          return ''
        }

        // 1) Tentar tabelas HTML comuns
        const rows = Array.from(doc.querySelectorAll('table tr'))
        rows.forEach((row) => {
          const cellEls = Array.from(row.querySelectorAll('th,td'))
          const cells = cellEls.map((c) => (c.textContent || '').trim())
          let imagem =
            firstValidImgInRow(row) ||
            cellEls.map((c) => extractImgSrcFromNode(c)).find((src) => src && !isJunkImgUrl(src)) ||
            (() => {
              const s = extractImgSrcFromNode(row)
              return s && !isJunkImgUrl(s) ? s : ''
            })()
          if (imagem) imagem = resolveUrl(imagem)
          if (!imagem) {
            for (const c of cellEls) {
              const html = typeof (c as HTMLElement).innerHTML === 'string' ? (c as HTMLElement).innerHTML : ''
              const abs = html.match(/https?:\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|webp|gif|svg)(?:\?[^\s"'<>]*)?/i)
              if (abs) {
                imagem = resolveUrl(abs[0])
                break
              }
              const proto = html.match(/\/\/[^\s"'<>]+\.(?:jpg|jpeg|png|webp|gif|svg)(?:\?[^\s"'<>]*)?/i)
              if (proto) {
                imagem = resolveUrl(`https:${proto[0]}`)
                break
              }
              const srcRel = html.match(/\bsrc\s*=\s*["']([^"']+)["']/i)
              if (srcRel?.[1]) {
                const cand = srcRel[1].replace(/&amp;/g, '&').trim()
                if (cand) imagem = resolveUrl(cand.startsWith('//') ? `https:${cand}` : cand)
                if (imagem && !isJunkImgUrl(imagem)) break
                imagem = ''
              }
            }
          }
          const texts = cells.map((t) => t.trim()).filter(Boolean)
          if (texts.length < 2 && !imagem) return
          const joined = cells.join(' ').toLowerCase()
          if (joined.includes('código') || joined.includes('codigo') || joined.includes('part') || joined.includes('refer') || joined.includes('preço') || joined.includes('preco') || joined.includes('descr')) {
            return // linha provável de cabeçalho
          }
          pushIfValid({
            codigo: texts[0] || '',
            nome: texts[1] || texts[0] || '',
            descricao: texts[2] || texts[1] || '',
            preco: cells.find((c) => /(\d+[.,]\d{2})/.test(c)) || '',
            imagem
          })
        })

        // 2) Tentar estruturas comuns em cards/listas de e-commerce
        if (itens.length === 0) {
          const cardSelectors = [
            '[data-part-number]',
            '[data-product-code]',
            '[data-sku]',
            '.product-item',
            '.product-card',
            '.slds-card'
          ]
          const cards = Array.from(doc.querySelectorAll(cardSelectors.join(',')))
          cards.forEach((card) => {
            const codeAttr =
              (card as HTMLElement).getAttribute('data-part-number') ||
              (card as HTMLElement).getAttribute('data-product-code') ||
              (card as HTMLElement).getAttribute('data-sku') ||
              ''
            const text = (card.textContent || '').replace(/\s+/g, ' ').trim()
            const mCode = text.match(/\b([A-Z0-9][A-Z0-9\-_.\/]{3,})\b/)
            const mPrice = text.match(/(\d{1,3}(?:[.\s]\d{3})*(?:[.,]\d{2})\s?(?:€|eur)?)/i)
            const titleEl = card.querySelector('h1,h2,h3,h4,.title,.name,[data-name],[data-title]')
            let imagem = extractImgSrcFromNode(card)
            if (imagem) imagem = resolveUrl(imagem)
            pushIfValid({
              codigo: codeAttr || (mCode ? mCode[1] : ''),
              nome: (titleEl?.textContent || '').trim() || text.slice(0, 140),
              descricao: text,
              preco: mPrice ? mPrice[1] : '',
              imagem
            })
          })
        }

        // 3) Tentar scripts com JSON embutido
        if (itens.length === 0) {
          const scripts = Array.from(doc.querySelectorAll('script'))
          scripts.forEach((s) => {
            const txt = (s.textContent || '').trim()
            if (!txt) return
            // Captura candidatos JSON com chaves comuns de catálogo.
            const candidates = [
              ...(txt.match(/\{[\s\S]*?"(?:parts|items|products|pecas|data)"[\s\S]*?\}/gi) || []),
              ...(txt.match(/\[[\s\S]*?\]/g) || [])
            ]
            for (const candidate of candidates) {
              try {
                const parsed = JSON.parse(candidate)
                if (Array.isArray(parsed)) {
                  parsed.forEach(pushIfValid)
                } else if (parsed && typeof parsed === 'object') {
                  const arr =
                    (Array.isArray((parsed as any).pecas) && (parsed as any).pecas) ||
                    (Array.isArray((parsed as any).parts) && (parsed as any).parts) ||
                    (Array.isArray((parsed as any).items) && (parsed as any).items) ||
                    (Array.isArray((parsed as any).products) && (parsed as any).products) ||
                    (Array.isArray((parsed as any).data) && (parsed as any).data) ||
                    null
                  if (arr) arr.forEach(pushIfValid)
                }
              } catch {
                // ignorar trecho não-JSON
              }
            }
          })
        }

        // 4) Fallback: texto visível da página (sites com HTML vazio mas texto copiado)
        if (itens.length === 0) {
          const textFromHtml = (doc.body?.innerText || doc.body?.textContent || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\r/g, '')
            .trim()
          if (textFromHtml.length >= 12) {
            if (looksLikeHomagClipboard(textFromHtml)) {
              itens = parseHomagPlainTextCatalog(textFromHtml)
            } else {
            const innerLines = textFromHtml.split(/\n/).map((l) => l.trim()).filter(Boolean)
            if (innerLines.length >= 2) {
              let homagBuf: string[] = []
              for (const line of innerLines) {
                const codigoHomag = matchHomagCodeLine(line)
                if (codigoHomag) {
                  if (homagBuf.length) {
                    pushIfValid({
                      codigo: codigoHomag,
                      nome: homagBuf[0],
                      descricao: homagBuf.slice(1).join(' ').trim() || homagBuf[0],
                    })
                    homagBuf = []
                  }
                } else {
                  homagBuf.push(line)
                }
              }
            }
            }
          }
        }
        if (itens.length > 0 && looksLikeHomagClipboard(doc.body?.innerText || '')) {
          const homagFromText = parseHomagPlainTextCatalog(doc.body?.innerText || '')
          if (homagFromText.length > itens.length) {
            itens = homagFromText
          } else if (homagFromText.length > 0) {
            itens = mergeHomagClipboardItems(
              itens.map((x) => ({
                codigo: String(x?.codigo ?? ''),
                nome: String(x?.nome ?? x?.name ?? ''),
                descricao: String(x?.descricao ?? x?.description ?? ''),
                preco: x?.preco != null ? String(x.preco) : undefined,
                imagem: x?.imagem != null ? String(x.imagem) : undefined,
              })),
              homagFromText
            )
          }
        }
      } catch {
        // segue para retorno vazio caso não consiga analisar HTML
      }
    } else if (trimRaw.startsWith('[') || trimRaw.startsWith('{')) {
      const parsed = JSON.parse(raw)
      if (Array.isArray(parsed)) itens = parsed
      else if (
        parsed &&
        typeof parsed === 'object' &&
        (Array.isArray((parsed as any).pecas) ||
          Array.isArray((parsed as any).parts) ||
          Array.isArray((parsed as any).items) ||
          Array.isArray((parsed as any).data) ||
          Array.isArray((parsed as any).itens))
      )
        itens =
          (parsed as any).pecas ??
          (parsed as any).parts ??
          (parsed as any).items ??
          (parsed as any).data ??
          (parsed as any).itens
      else itens = [parsed]
    } else {
      const lines = raw.split(/\r?\n/).map((l: string) => l.trim()).filter(Boolean)
      if (lines.length < 1) return []

      const looksLikeDelimitedTable =
        (lines[0].includes(';') || lines[0].includes(',')) &&
        /codigo|código|nome|descri|pre[cç]o|price|sku|code/i.test(lines[0])

      if (looksLikeDelimitedTable) {
        const sep = lines[0].includes(';') ? ';' : ','
        const headers = csvSplit(lines[0], sep).map((h: string) => h.trim().replace(/^["']|["']$/g, ''))
        for (let i = 1; i < lines.length; i++) {
          const vals = csvSplit(lines[i], sep).map((v: string) => v.trim().replace(/^["']|["']$/g, ''))
          const obj: Record<string, string> = {}
          headers.forEach((h, j) => { obj[h] = vals[j] ?? '' })
          itens.push(obj)
        }
      } else {
        if (looksLikeHomagClipboard(raw)) {
          itens = parseHomagPlainTextCatalog(raw)
        }
        if (itens.length === 0) {
        // HOMAG / catálogos: descrição seguida de código (2006807481, 2-006-80-7481, 2006808181R, R2006215960)
        const homagItemsParsed: Array<{ codigo: string; nome: string; descricao: string }> = []
        let homagBuf: string[] = []
        for (const line of lines) {
          const t = line.trim()
          if (!t) continue
          const codigoHomag = matchHomagCodeLine(t)
          if (codigoHomag) {
            if (homagBuf.length) {
              homagItemsParsed.push({
                codigo: codigoHomag,
                nome: homagBuf[0],
                descricao: homagBuf.slice(1).join(' ').trim() || homagBuf[0]
              })
              homagBuf = []
            }
          } else {
            homagBuf.push(t)
          }
        }
        if (homagBuf.length && homagItemsParsed.length) {
          const last = homagItemsParsed[homagItemsParsed.length - 1]
          last.descricao = [last.descricao, ...homagBuf].join(' ').trim()
        }
        const homagCodeLineCount = lines.filter((l) => matchHomagCodeLine(l.trim()) != null).length
        const useHomagLinear =
          homagItemsParsed.length > 0 && homagItemsParsed.length === homagCodeLineCount

        if (useHomagLinear) {
          itens = homagItemsParsed
        } else {
        const codeRegex = /\b[A-Z0-9][A-Z0-9\-_.\/]{3,}\b/i
        const numericCodeRegex = /^\d{7,}$/
        const priceRegex = /(\d{1,3}(?:[.\s]\d{3})*(?:[.,]\d{2})\s?(?:€|eur|usd|us\$|r\$)?)$/i
        const imageUrlLine =
          /^\s*https?:\/\/[^\s<>"']+\.(jpg|jpeg|png|webp|gif|svg)(?:\?[^\s<>"']*)?\s*$/i
        let current: { codigo?: string; nome?: string; descricao?: string; preco?: string; imagem?: string } | null = null
        let pendingImagem = ''

        const flushCurrent = () => {
          if (!current) return
          if (current.codigo || current.nome || current.descricao) {
            const row = { ...current }
            if (pendingImagem && !row.imagem) row.imagem = pendingImagem
            itens.push(row)
            pendingImagem = ''
          }
          current = null
        }

        const blocks = raw
          .split(/\r?\n\s*\r?\n/g)
          .map((block: string) => block.split(/\r?\n/).map((line: string) => line.trim()).filter(Boolean))
          .filter((block: string[]) => block.length > 0)

        const looksLikeTrailingCodeCatalog =
          blocks.length >= 2 &&
          blocks.filter((block: string[]) => numericCodeRegex.test(block[block.length - 1] || '')).length >= Math.max(2, Math.ceil(blocks.length * 0.6))

        if (looksLikeTrailingCodeCatalog) {
          blocks.forEach((block: string[]) => {
            const lastLine = block[block.length - 1] || ''
            if (!numericCodeRegex.test(lastLine)) return

            let contentLines = block.slice(0, -1)
            const imgIdx = contentLines.findIndex((ln: string) => imageUrlLine.test(ln))
            let imagemBloco = ''
            if (imgIdx >= 0) {
              imagemBloco = contentLines[imgIdx].trim()
              contentLines = contentLines.filter((_, index) => index !== imgIdx)
            }
            const precoIndex = contentLines.findIndex((line: string) => priceRegex.test(line))
            const preco = precoIndex >= 0 ? (contentLines[precoIndex].match(priceRegex)?.[1] || '') : ''
            const textLines = precoIndex >= 0
              ? contentLines.filter((_, index) => index !== precoIndex)
              : contentLines

            const nome = textLines[0] || lastLine
            const descricao = textLines.slice(1).join(' ').trim()

            itens.push({
              codigo: lastLine,
              nome,
              descricao: descricao || nome,
              preco,
              ...(imagemBloco ? { imagem: imagemBloco } : {})
            })
          })
        } else for (const line of lines) {
          if (imageUrlLine.test(line)) {
            const url = line.trim()
            if (current && (current.codigo || current.nome || current.descricao)) {
              current.imagem = url
            } else {
              pendingImagem = url
            }
            continue
          }
          const priceMatch = line.match(priceRegex)
          const normalizedLine = line.replace(/\s+/g, ' ').trim()
          const isLikelyCodeLine =
            !!normalizedLine.match(codeRegex) &&
            normalizedLine.length <= 60 &&
            !/\s{2,}/.test(normalizedLine) &&
            normalizedLine.split(' ').length <= 3

          if (isLikelyCodeLine) {
            if (current && !current.codigo && (current.nome || current.descricao)) {
              current.codigo = normalizedLine
              if (pendingImagem && !current.imagem) {
                current.imagem = pendingImagem
                pendingImagem = ''
              }
            } else {
              flushCurrent()
              current = { codigo: normalizedLine }
              if (pendingImagem) {
                current.imagem = pendingImagem
                pendingImagem = ''
              }
            }
            continue
          }

          if (!current) {
            current = {}
          }

          if (priceMatch && !current.preco) {
            current.preco = priceMatch[1]
            const withoutPrice = normalizedLine.replace(priceRegex, '').trim()
            if (withoutPrice) {
              if (!current.nome) current.nome = withoutPrice
              else current.descricao = current.descricao ? `${current.descricao} ${withoutPrice}` : withoutPrice
            }
            continue
          }

          if (!current.nome) current.nome = normalizedLine
          else current.descricao = current.descricao ? `${current.descricao} ${normalizedLine}` : normalizedLine
        }

        flushCurrent()
        }
        }
      }
    }
    // Normaliza e remove duplicados da própria importação.
    const absolutizeImagem = (p: PecaBiblioteca): PecaBiblioteca => {
      const im = (p.imagem || '').trim()
      if (!im || !lojaOrigin) return p
      if (im.startsWith('/') && !im.startsWith('//')) {
        try {
          return { ...p, imagem: new URL(im, `${lojaOrigin}/`).href }
        } catch {
          return p
        }
      }
      return p
    }
    const mapped = itens.map((item, idx) => absolutizeImagem(mapItemToPecaBiblioteca(item, idx)))
    return mapped.filter((p) => {
      const codigoNorm = normalizeImportKey(p.codigo)
      const nomeNorm = normalizeImportKey(p.nome)
      return Boolean(codigoNorm || nomeNorm)
    })
  }, [])

  const processarTextoImportacaoPecas = useCallback((
    raw: string,
    plainFallback = ''
  ): { pecas: PecaBiblioteca[] } | { error: string } => {
    const trimmed = raw.trim()
    if (!trimmed) {
      return {
        error:
          (t as any)?.importacaoColarVazio ??
          'Cole o conteúdo copiado do site na caixa abaixo (Ctrl+A no site, Ctrl+C, depois Ctrl+V).',
      }
    }
    if (/^https?:\/\//i.test(trimmed) && !trimmed.includes('\n')) {
      return {
        error:
          t?.importacaoColarUrlNaoSuportado ??
          'Cole o conteúdo da página (Ctrl+A no site), não só o endereço. Para URL use «Buscar da URL» na aba Importação.',
      }
    }
    try {
      const paginaColagem =
        (/^https?:\/\//i.test(urlImportacaoPecas.trim()) && urlImportacaoPecas.trim()) ||
        (/^https?:\/\//i.test(importacaoLojaBaseUrl.trim()) ? importacaoLojaBaseUrl.trim() : '')
      const tryParse = (text: string) => parseRawToPecas(text, importacaoLojaBaseUrl, paginaColagem)

      let pecas = tryParse(trimmed)
      const fb = plainFallback.trim()
      const plainForHomag = fb || trimmed
      if (looksLikeHomagClipboard(plainForHomag)) {
        const homagItens = parseHomagPlainTextCatalog(plainForHomag)
        if (homagItens.length > 0) {
          const homagPecas = homagItens.map((item, idx) =>
            mapItemToPecaBiblioteca(item, idx)
          )
          if (homagPecas.length > pecas.length) {
            pecas = homagPecas
          } else if (pecas.length > 0) {
            const merged = mergeHomagClipboardItems(
              pecas.map((p) => ({
                codigo: p.codigo,
                nome: p.nome,
                descricao: p.descricao,
                preco: p.preco,
                imagem: p.imagem,
              })),
              homagItens
            )
            pecas = merged.map((item, idx) => mapItemToPecaBiblioteca(item, idx))
          } else {
            pecas = homagPecas
          }
        }
      }
      if (pecas.length === 0 && fb && fb !== trimmed) {
        pecas = tryParse(fb)
      }
      if (pecas.length === 0 && /<[a-z][\s\S]*>/i.test(trimmed)) {
        const stripped = trimmed
          .replace(/<script[\s\S]*?<\/script>/gi, '\n')
          .replace(/<style[\s\S]*?<\/style>/gi, '\n')
          .replace(/<br\s*\/?>/gi, '\n')
          .replace(/<\/(p|div|tr|li|h[1-6]|td|th)>/gi, '\n')
          .replace(/<[^>]+>/g, ' ')
          .replace(/[ \t]+\n/g, '\n')
          .replace(/\n{3,}/g, '\n\n')
          .trim()
        if (stripped.length >= 12 && stripped !== trimmed) {
          pecas = tryParse(stripped)
        }
      }
      if (pecas.length === 0) {
        return {
          error:
            t?.importacaoNenhumaLinha ??
            'Nenhuma peça reconhecida. Copie o conteúdo visível da página (Ctrl+A no site) ou use CSV/JSON.',
        }
      }
      return { pecas }
    } catch (err: any) {
      return {
        error:
          err?.message ||
          (t?.importacaoErroJsonInvalido ?? 'Conteúdo inválido. Use JSON ou CSV com cabeçalhos na primeira linha.'),
      }
    }
  }, [parseRawToPecas, t, importacaoLojaBaseUrl, urlImportacaoPecas])

  const importarPecaDoCatalogoUrl = useCallback(
    async (codigoDigitado: string, opts?: { silent?: boolean }): Promise<PecaBiblioteca | null> => {
      const cod = String(codigoDigitado || '').trim()
      const silent = opts?.silent === true
      const template = pecaLookupUrlTemplate.trim()
      if (!cod) return null
      if (!template) {
        if (!silent) {
          window.alert(
            (t as any)?.pecaLookupSemTemplate ||
              'Configure primeiro a «URL do catálogo por código» em Importação de peças (use {codigo} no endereço).'
          )
        }
        return null
      }
      const url = buildPecaCatalogoUrlFromTemplate(template, cod)
      if (!url) {
        if (!silent) {
          window.alert(
            (t as any)?.pecaLookupPlaceholderInvalido ||
              'A URL modelo deve ser https://… e incluir {codigo}, {codigoPath} ou * onde entra o código da peça.'
          )
        }
        return null
      }

      if (codigoExisteNaBibliotecaPecas(cod, pecasBiblioteca)) {
        const alvo = variantesCodigoPecaBiblioteca(cod)
        return (
          pecasBiblioteca.find((p) =>
            variantesCodigoPecaBiblioteca(p.codigo).some((v) => alvo.includes(v))
          ) ?? null
        )
      }

      setPecaLookupLoading(true)
      try {
        const res = await fetch('/api/import-from-url', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ url }),
        })
        const text = await res.text()
        let json: { ok?: boolean; error?: string; data?: string } = {}
        try {
          json = text.trim() ? JSON.parse(text) : {}
        } catch {
          if (!silent) {
            window.alert((t as any)?.pecaLookupErro || 'Resposta inválida do servidor.')
          }
          return null
        }
        if (!res.ok || !json.ok || typeof json.data !== 'string') {
          if (!silent) {
            window.alert(json.error || (t as any)?.pecaLookupErro || 'Não foi possível obter a página do catálogo.')
          }
          return null
        }
        let parsed: PecaBiblioteca[]
        try {
          parsed = parseRawToPecas(json.data, importacaoLojaBaseUrl, url)
        } catch {
          if (!silent) {
            window.alert(
              (t as any)?.pecaLookupErroParse || 'Não foi possível extrair dados de peça nesta página (HTML/JSON).'
            )
          }
          return null
        }
        if (!parsed.length) {
          if (!silent) {
            window.alert(
              (t as any)?.pecaLookupNenhumResultado ||
                'Nenhuma peça reconhecida na página devolvida. Verifique a URL ou copie o HTML para Importação.'
            )
          }
          return null
        }
        const q = normalizeImportKey(cod)
        const best =
          parsed.find((p) => normalizeImportKey(p.codigo) === q) ||
          parsed.find(
            (p) =>
              normalizeImportKey(p.codigo).includes(q) ||
              (q.length >= 4 && q.includes(normalizeImportKey(p.codigo)))
          ) ||
          parsed[0]

        const nova: PecaBiblioteca = {
          ...best,
          id: `pec-url-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
          codigo: (best.codigo && String(best.codigo).trim()) || cod,
          nome: (best.nome && String(best.nome).trim()) || (best.descricao && String(best.descricao).trim()) || cod,
          dataCriacao: new Date().toISOString(),
        }
        const comCat = preencherPecaBibliotecaComUltimaCategoriaSeVazio(
          nova,
          ultimoGrupoSelecionado,
          ultimoSubgrupoSelecionado,
          categoriasPecas,
          subcategoriasPecas
        )
        let inserida: PecaBiblioteca = comCat
        setPecasBiblioteca((prev) => {
          const alvoCodigo = variantesCodigoPecaBiblioteca(comCat.codigo)
          const dup = prev.find((p) =>
            variantesCodigoPecaBiblioteca(p.codigo).some((v) => alvoCodigo.includes(v))
          )
          if (dup) {
            inserida = dup
            return prev
          }
          const nextRaw = [...prev, comCat]
          const next = garantirNumerosSequenciaPecaBiblioteca(nextRaw, categoriasPecas).lista
          void saveData('nonato-pecas-biblioteca', next)
          return next
        })
        return inserida
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e)
        if (!silent) window.alert(msg || (t as any)?.pecaLookupErro || 'Erro ao contactar o catálogo.')
        return null
      } finally {
        setPecaLookupLoading(false)
      }
    },
    [
      pecaLookupUrlTemplate,
      importacaoLojaBaseUrl,
      parseRawToPecas,
      pecasBiblioteca,
      t,
      ultimoGrupoSelecionado,
      ultimoSubgrupoSelecionado,
      categoriasPecas,
      subcategoriasPecas,
    ]
  )

  useEffect(() => {
    void saveData(NONATO_PECA_LOOKUP_URL_TEMPLATE_KEY, pecaLookupUrlTemplate)
  }, [pecaLookupUrlTemplate])

  const handleBuscarImportacaoUrl = useCallback(async (urlOverride?: string) => {
    const url = (urlOverride ?? urlImportacaoPecas).trim()
    if (urlOverride) setUrlImportacaoPecas(urlOverride)
    const isHomagUrl = /shop\.homag\.com/i.test(url)
    const autoSelectGuiaPlataforma = () => {
      if (typeof navigator === 'undefined') return
      const ua = navigator.userAgent.toLowerCase()
      if (ua.includes('ipad') || (ua.includes('macintosh') && 'ontouchend' in document)) {
        setImportacaoGuiaPlataforma('ipad')
      } else if (ua.includes('android')) {
        setImportacaoGuiaPlataforma('android')
      } else {
        setImportacaoGuiaPlataforma('windows')
      }
    }
    if (!url) {
      setImportacaoUrlError(t?.importacaoUrlObrigatoria ?? 'Informe a URL da lista de peças.')
      return
    }
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
      setImportacaoUrlError('A URL deve começar com http:// ou https://')
      return
    }
    setImportacaoUrlError(null)
    setImportacaoPreview(null)
    setImportacaoUrlLoading(true)

    const tryParseAndPreview = (raw: string): boolean => {
      try {
        const pecas = parseRawToPecas(raw, importacaoLojaBaseUrl, url)
        if (pecas.length === 0) return false
        return aplicarPreviewImportacaoFiltrado(pecas, { notificar: true })
      } catch {
        return false
      }
    }

    let apiError: string | null = null
    try {
      // 1) Tentar primeiro pela API do servidor (evita CORS; funciona para a maioria dos URLs)
      const res = await fetch('/api/import-from-url', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
      })
      const text = await res.text()
      let json: { ok?: boolean; error?: string; data?: string } = { ok: false }
      if (text.trim()) {
        try {
          json = JSON.parse(text)
        } catch {
          apiError = (t?.importacaoErroRespostaInvalida ?? 'Resposta inválida do servidor.') + (res.status ? ` (${res.status})` : '')
        }
      }
      if (!apiError && res.ok && json.ok && typeof json.data === 'string') {
        if (tryParseAndPreview(json.data)) {
          setImportacaoUrlLoading(false)
          return
        }
        setImportacaoUrlError(t?.importacaoErroJsonInvalido ?? 'O conteúdo da URL não é um JSON ou CSV válido.')
        if (isHomagUrl) {
          autoSelectGuiaPlataforma()
          setShowImportacaoGuiaHomag(true)
        }
        setImportacaoUrlLoading(false)
        return
      }
      if (!apiError) {
        if (!text.trim()) apiError = t?.importacaoErroRespostaVazia ?? 'O servidor respondeu sem dados.'
        else if (json?.error) apiError = json.error
        else apiError = t?.importacaoErroBusca ?? 'Erro ao buscar a URL.'
      }

      // 2) Se a API falhou (modo demo, 404, rota em falta após restauro, etc.), tentar buscar a URL diretamente no browser
      try {
        const directRes = await fetch(url, {
          method: 'GET',
          headers: { 'Accept': 'application/json, text/csv, text/plain, */*' },
          mode: 'cors'
        })
        if (directRes.ok) {
          const raw = await directRes.text()
          if (tryParseAndPreview(raw)) {
            setImportacaoUrlLoading(false)
            return
          }
        }
      } catch (_) {
        // Fallback direto falhou (ex.: CORS)
      }
      setImportacaoUrlError(String(apiError).toLowerCase().includes('fetch failed') ? (t?.importacaoErroFetchFailed ?? 'Não foi possível aceder à URL. Verifique o endereço e a ligação.') : apiError)
      if (isHomagUrl) {
        autoSelectGuiaPlataforma()
        setShowImportacaoGuiaHomag(true)
      }
    } catch (e: any) {
      // Falha ao chamar a API (rede, etc.) — tentar buscar a URL diretamente no browser
      try {
        const directRes = await fetch(url, {
          method: 'GET',
          headers: { 'Accept': 'application/json, text/csv, text/plain, */*' },
          mode: 'cors'
        })
        if (directRes.ok) {
          const raw = await directRes.text()
          if (tryParseAndPreview(raw)) {
            setImportacaoUrlLoading(false)
            return
          }
        }
      } catch (_) {}
      const msg = e?.message || String(e)
      const isNetwork = msg && String(msg).toLowerCase().includes('fetch failed')
      setImportacaoUrlError(isNetwork ? (t?.importacaoErroFetchFailed ?? 'Não foi possível aceder à URL. Verifique o endereço e a ligação.') : (msg || (t?.importacaoErroBusca ?? 'Erro ao buscar a URL.')))
      if (isHomagUrl) {
        autoSelectGuiaPlataforma()
        setShowImportacaoGuiaHomag(true)
      }
    } finally {
      setImportacaoUrlLoading(false)
    }
  }, [urlImportacaoPecas, t, parseRawToPecas, importacaoLojaBaseUrl, aplicarPreviewImportacaoFiltrado])

  const abrirSiteImportacaoNoNavegador = useCallback(() => {
    const resolveOpenableUrl = (raw: string): string | null => {
      const u = raw.trim()
      if (!u) return null
      if (u.startsWith('http://') || u.startsWith('https://')) {
        try {
          return new URL(u).href
        } catch {
          return null
        }
      }
      try {
        const withProto = u.startsWith('//') ? `https:${u}` : `https://${u.replace(/^\/+/, '')}`
        const parsed = new URL(withProto)
        if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null
        return parsed.href
      } catch {
        return null
      }
    }
    const target =
      resolveOpenableUrl(urlImportacaoPecas) || resolveOpenableUrl(importacaoLojaBaseUrl)
    if (!target) {
      alert(t?.importacaoAbrirSiteInformeUrl ?? 'Indique uma URL válida no campo da lista ou em «URL base da loja».')
      return
    }
    window.open(target, '_blank', 'noopener,noreferrer')
  }, [urlImportacaoPecas, importacaoLojaBaseUrl, t])

  const aplicarResultadoColagemCatalogo = useCallback((
    result: { pecas: PecaBiblioteca[] } | { error: string },
    textoColado: string
  ) => {
    if ('error' in result) {
      setImportacaoUrlError(result.error)
      setImportacaoPreview(null)
      setImportacaoDuplicadasIgnoradas(0)
      return
    }
    setImportacaoTextoColado(textoColado)
    const { ok, novas } = processarDuplicadosImportacao(result.pecas, { notificar: true })
    if (!ok) return
    if (novas.length === 1) {
      const p = novas[0]
      setShowBibliotecaPecasForm(true)
      setEditingPecaBiblioteca(null)
      setPecaBibliotecaForm((prev) => ({
        ...prev,
        id: '',
        nome: p.nome || '',
        codigo: p.codigo || '',
        preco: p.preco || '',
        descricao: p.descricao || '',
        imagem: p.imagem || prev.imagem,
        dataCriacao: prev.dataCriacao || new Date().toISOString(),
      }))
      if (p.imagem) setPecaBibliotecaImagemUrlDraft('')
    } else if (novas.length > 1) {
      setAbaBibliotecaPecas('importacao')
    }
  }, [processarDuplicadosImportacao, t, pecasBiblioteca])

  const executarColagemCatalogo = useCallback((
    html: string,
    plain: string,
    opts?: { mergeComExistente?: boolean }
  ) => {
    const merge = opts?.mergeComExistente !== false
    const p = String(plain || '').trim()
    const h = String(html || '').trim()
    const { raw, plainFallback } = pickBestCatalogRawFromClipboard(h, p)
    const incoming = (raw || p || h).trim()

    if (!incoming) {
      setImportacaoUrlError(
        (t as any)?.importacaoColarVazio ??
          'Cole o conteúdo copiado do site na caixa abaixo (Ctrl+A no site, Ctrl+C, depois Ctrl+V).'
      )
      setImportacaoPreview(null)
      return
    }

    const prev = merge ? importacaoTextoColado.trim() : ''
    const merged = merge && prev.length ? `${prev}\n\n${incoming}` : incoming
    setImportacaoTextoColado(merged)

    if (/^https?:\/\//i.test(p) && !p.includes('\n') && h.length < 40 && incoming === p) {
      setUrlImportacaoPecas(p)
      try {
        const origin = new URL(p).origin
        if (!importacaoLojaBaseUrl.trim()) setImportacaoLojaBaseUrl(origin)
      } catch {
        /* ignorar */
      }
      setImportacaoUrlError(
        (t as any)?.importacaoColarUrlUsarBuscar ??
          'Copie o conteúdo da página (Ctrl+A no site), não só o endereço. O link foi guardado acima se quiser «Buscar da URL».'
      )
      setImportacaoPreview(null)
      return
    }

    const result = processarTextoImportacaoPecas(merged, plainFallback || p)
    aplicarResultadoColagemCatalogo(result, merged)
  }, [
    aplicarResultadoColagemCatalogo,
    processarTextoImportacaoPecas,
    importacaoLojaBaseUrl,
    importacaoTextoColado,
    t,
  ])

  const handlePasteCatalogoPecaBiblioteca = useCallback(
    (e: React.ClipboardEvent | ClipboardEvent) => {
      const cd = e.clipboardData
      if (!cd) return
      const html = cd.getData('text/html') || ''
      const plain = cd.getData('text/plain') || ''
      if (!plain.trim() && html.trim().length < 20) return

      e.preventDefault()
      e.stopPropagation()
      executarColagemCatalogo(html, plain, { mergeComExistente: false })
    },
    [executarColagemCatalogo]
  )

  useLayoutEffect(() => {
    if (!showBibliotecaPecasForm) return
    const root = pecaBibliotecaFormPasteRootRef.current
    if (!root) return
    const listener = (ev: Event) => {
      const ce = ev as ClipboardEvent
      handlePasteCatalogoPecaBiblioteca(ce)
      if (!ce.defaultPrevented) handlePasteImagemPecaBiblioteca(ce)
    }
    root.addEventListener('paste', listener, true)
    return () => root.removeEventListener('paste', listener, true)
  }, [
    showBibliotecaPecasForm,
    editingPecaBiblioteca?.id,
    handlePasteCatalogoPecaBiblioteca,
    handlePasteImagemPecaBiblioteca,
  ])

  /** Colagem a partir do site: preferir `text/html` (tabelas + &lt;img&gt;) em vez de só texto plano. */
  const handleImportacaoPecasPaste = useCallback((e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const html = e.clipboardData?.getData('text/html') || ''
    const plain = e.clipboardData?.getData('text/plain') || ''
    if (!plain.trim() && html.trim().length < 20) return
    e.preventDefault()
    executarColagemCatalogo(html, plain, { mergeComExistente: true })
  }, [executarColagemCatalogo])

  const handleImportacaoFicheiro = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    setImportacaoUrlError(null)
    setImportacaoPreview(null)
    const reader = new FileReader()
    reader.onload = () => {
      try {
        const raw = String(reader.result ?? '')
        const pecas = parseRawToPecas(raw, importacaoLojaBaseUrl)
        if (pecas.length === 0) {
          setImportacaoUrlError(t?.importacaoNenhumaLinha ?? 'Nenhuma lista encontrada no ficheiro. Use CSV (1ª linha = cabeçalhos) ou JSON.')
          return
        }
        aplicarPreviewImportacaoFiltrado(pecas, { notificar: true })
      } catch (err: any) {
        setImportacaoUrlError(err?.message || (t?.importacaoErroJsonInvalido ?? 'Ficheiro inválido. Use CSV ou JSON.'))
      }
    }
    reader.readAsText(file, 'UTF-8')
    e.target.value = ''
  }, [parseRawToPecas, t, importacaoLojaBaseUrl, aplicarPreviewImportacaoFiltrado])

  const limparEstadoColagemImportacao = useCallback(() => {
    setImportacaoPreview(null)
    setImportacaoAnaliseColagem(null)
    setImportacaoTextoColado('')
    setImportacaoDuplicadasIgnoradas(0)
    setImportacaoUrlError(null)
  }, [])

  const perguntarLimparColagemAposImportacao = useCallback(
    (quantidadeNovas: number) => {
      const pergunta = String(
        (t as any)?.importacaoConfirmarLimparColagem ??
          'Importação concluída: {count} peça(s) enviada(s) para a fila amarela.\n\nDeseja apagar o texto colado e limpar a análise para uma nova importação?'
      ).replace('{count}', String(quantidadeNovas))
      if (window.confirm(pergunta)) {
        limparEstadoColagemImportacao()
      } else {
        setImportacaoPreview(null)
        setImportacaoAnaliseColagem(null)
        setImportacaoDuplicadasIgnoradas(0)
        setImportacaoUrlError(null)
      }
    },
    [limparEstadoColagemImportacao, t]
  )

  const executarEnvioImportacaoParaFila = useCallback(
    (pecasOrigem: PecaBiblioteca[]) => {
      if (!pecasOrigem.length) return

      const existentes = pecasBiblioteca
      const { novas: novasFiltradas, duplicadasCatalogo, duplicadasFila, duplicadasLote, semCodigo } =
        separarPecasImportacao(pecasOrigem)
      const ignoradasTotal =
        duplicadasCatalogo.length + duplicadasFila.length + duplicadasLote.length + semCodigo.length

      if (novasFiltradas.length === 0) {
        const detalhe = montarMensagemImportacaoIgnoradas({
          duplicadasCatalogo,
          duplicadasFila,
          duplicadasLote,
          semCodigo,
        })
        const msgBase =
          duplicadasCatalogo.length > 0
            ? String(
                (t as any)?.importacaoPreviewTodasDuplicadas ??
                  'Nenhuma peça nova para adicionar (já existem no catálogo da biblioteca).'
              ).replace('{count}', String(duplicadasCatalogo.length))
            : duplicadasFila.length > 0
              ? String(
                  (t as any)?.importacaoPreviewTodasNaFila ??
                    'Nenhuma peça nova: {count} já estão na fila amarela (pendentes).'
                ).replace('{count}', String(duplicadasFila.length))
              : (t as any)?.importacaoSemNovidades ?? 'Nenhuma peça nova para adicionar.'
        const codes = listarCodigosPecasImport(
          duplicadasCatalogo.length
            ? duplicadasCatalogo
            : duplicadasFila.length
              ? duplicadasFila
              : pecasOrigem
        )
        alert(
          detalhe
            ? `${msgBase}\n\n${detalhe}${codes ? `\n\n${(t as any)?.importacaoCodigosDuplicadosLista || 'Códigos:'} ${codes}` : ''}`
            : codes
              ? `${msgBase}\n\n${(t as any)?.importacaoCodigosDuplicadosLista || 'Códigos:'} ${codes}`
              : msgBase
        )
        setImportacaoDuplicadasIgnoradas(ignoradasTotal)
        setImportacaoUrlError(msgBase)
        return
      }

      const novos: PecaBiblioteca[] = novasFiltradas.map((p, i) => ({
        ...p,
        id: `import-${Date.now()}-${i}-${Math.random().toString(36).slice(2, 9)}`,
        dataCriacao: new Date().toISOString(),
        importacaoPendente: true,
      }))

      if (ignoradasTotal > 0) {
        const detalhe = montarMensagemImportacaoIgnoradas({
          duplicadasCatalogo,
          duplicadasFila,
          duplicadasLote,
          semCodigo,
        })
        const codes = listarCodigosPecasImport([...duplicadasCatalogo, ...duplicadasFila, ...duplicadasLote])
        alert(
          `${String(
            (t as any)?.importacaoParcialDuplicadas ??
              '{novas} peça(s) enviada(s) para a fila. {ignoradas} ignorada(s).'
          )
            .replace('{novas}', String(novos.length))
            .replace('{ignoradas}', String(ignoradasTotal))}${detalhe ? `\n\n${detalhe}` : ''}${
            codes ? `\n\n${(t as any)?.importacaoCodigosIgnorados || 'Códigos ignorados:'} ${codes}` : ''
          }`
        )
        setImportacaoDuplicadasIgnoradas(ignoradasTotal)
      }

      const classificadosAutomaticamente = aplicarRegrasClassificacaoEmLista(novos, true)
      const merged = [...existentes, ...classificadosAutomaticamente.lista]
      const { lista: atualizadoNormalizado } = garantirNumerosSequenciaPecaBiblioteca(
        merged.map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca)),
        categoriasPecas
      )
      setPecasBiblioteca(atualizadoNormalizado)
      const mensagemBase =
        t?.importacaoSucesso ??
        `${novos.length} peça(s) enviada(s) para a fila. Abra cada uma e use Salvar para integrar ao catálogo da Biblioteca.`
      const mensagemFinal =
        classificadosAutomaticamente.alteradas > 0
          ? `${mensagemBase} ${classificadosAutomaticamente.alteradas} já foram classificadas automaticamente.`
          : mensagemBase
      if (ignoradasTotal === 0) {
        alert(mensagemFinal)
      }
      perguntarLimparColagemAposImportacao(novos.length)
      void saveData('nonato-pecas-biblioteca', atualizadoNormalizado).catch((err) => {
        console.error('[importação fila]', err)
        alert(
          (t as any)?.importacaoErroGravarFila ??
            'Não foi possível gravar na biblioteca. O armazenamento do navegador pode estar cheio — liberte espaço ou reduza imagens nas peças.'
        )
      })
    },
    [
      aplicarRegrasClassificacaoEmLista,
      categoriasPecas,
      perguntarLimparColagemAposImportacao,
      montarMensagemImportacaoIgnoradas,
      pecasBiblioteca,
      separarPecasImportacao,
      t,
    ]
  )

  const handleImportacaoColarTexto = useCallback(() => {
    const raw = importacaoTextoColado.trim()
    if (!raw) {
      setImportacaoUrlError(
        (t as any)?.importacaoColarVazio ??
          'Cole o conteúdo copiado do site na caixa abaixo (Ctrl+A no site, Ctrl+C, depois Ctrl+V).'
      )
      setImportacaoPreview(null)
      return
    }

    if (importacaoPreview && importacaoPreview.length > 0) {
      executarEnvioImportacaoParaFila(importacaoPreview)
      return
    }

    const result = processarTextoImportacaoPecas(raw, raw)
    if ('error' in result) {
      setImportacaoUrlError(result.error)
      setImportacaoPreview(null)
      setImportacaoDuplicadasIgnoradas(0)
      return
    }

    const filtrado = processarDuplicadosImportacao(result.pecas, { notificar: false })
    if (!filtrado.ok || filtrado.novas.length === 0) {
      processarDuplicadosImportacao(result.pecas, { notificar: true })
      return
    }

    executarEnvioImportacaoParaFila(filtrado.novas)
  }, [
    executarEnvioImportacaoParaFila,
    importacaoPreview,
    importacaoTextoColado,
    processarDuplicadosImportacao,
    processarTextoImportacaoPecas,
    t,
  ])

  const renderPainelPreviewImportacao = useCallback(() => {
    const analise = importacaoAnaliseColagem
    const novas = importacaoPreview ?? analise?.novas ?? []
    const temAnalise =
      analise &&
      (analise.totalColagem > 0 ||
        analise.duplicadasCatalogo.length > 0 ||
        analise.duplicadasFila.length > 0 ||
        novas.length > 0)
    if (!temAnalise && novas.length === 0) return null

    const hubT: Record<string, string> = (safeT || {}) as Record<string, string>
    const totalColagem = analise?.totalColagem ?? novas.length
    const duplicadasCatalogo = analise?.duplicadasCatalogo ?? []
    const duplicadasFila = analise?.duplicadasFila ?? []
    const duplicadasLote = analise?.duplicadasLote ?? []
    const semCodigo = analise?.semCodigo ?? []
    const rejeitadasBiblioteca = duplicadasCatalogo.length
    const rejeitadasOutras = duplicadasFila.length + duplicadasLote.length + semCodigo.length

    const renderTabelaPecas = (
      pecas: PecaBiblioteca[],
      variant: 'vermelho' | 'amarelo',
      max = 50
    ) => {
      const slice = pecas.slice(0, max)
      const theadClass =
        variant === 'vermelho'
          ? 'importacao-pecas-tabela__head--vermelho'
          : 'importacao-pecas-tabela__head--amarelo'
      const wrapClass =
        variant === 'vermelho'
          ? 'importacao-pecas-tabela-wrap--vermelho'
          : 'importacao-pecas-tabela-wrap--amarelo'
      return (
        <div className={`importacao-pecas-tabela-wrap ${wrapClass}`}>
          <table className="importacao-pecas-tabela">
            <thead>
              <tr className={theadClass}>
                <th>{hubT.codigo || 'Código'}</th>
                <th>{hubT.nome || 'Nome'}</th>
                <th>{hubT.preco || 'Preço'}</th>
                <th>{(hubT as any).importacaoPreviewColImagem || 'Img'}</th>
              </tr>
            </thead>
            <tbody>
              {slice.map((p, i) => (
                <tr key={`${variant}-${p.codigo || 'n'}-${i}`}>
                  <td>{p.codigo || '—'}</td>
                  <td>
                    {(p.nome || p.descricao || '').slice(0, 80)}
                    {(p.nome || p.descricao || '').length > 80 ? '…' : ''}
                  </td>
                  <td>{p.preco || '—'}</td>
                  <td className="importacao-pecas-tabela__img-cell">
                    {p.imagem ? (
                      <img
                        src={pecaBibliotecaSrcImagemDisplay(p.imagem)}
                        alt=""
                        referrerPolicy="no-referrer"
                      />
                    ) : (
                      <span>—</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {pecas.length > max ? (
            <p className="importacao-pecas-tabela__mais">
              … +{pecas.length - max} {hubT.importacaoMaisItens || 'mais'}
            </p>
          ) : null}
        </div>
      )
    }

    return (
      <div ref={importacaoPreviewPanelRef} className="importacao-pecas-preview-panel">
        <div className="importacao-pecas-resumo">
          <strong>
            {(hubT as any).importacaoAnaliseTitulo || 'Análise da colagem'}
          </strong>
          <p>
            {String(
              (hubT as any).importacaoAnaliseResumo ||
                'Foram detectadas {total} peça(s): {novas} nova(s) para cadastrar, {catalogo} já existente(s) na biblioteca.'
            )
              .replace('{total}', String(totalColagem))
              .replace('{novas}', String(novas.length))
              .replace('{catalogo}', String(rejeitadasBiblioteca))}
            {rejeitadasOutras > 0
              ? ` ${String(
                  (hubT as any).importacaoAnaliseResumoExtra ||
                    '({extra} ignorada(s): fila amarela, repetidas na colagem ou sem código).'
                ).replace('{extra}', String(rejeitadasOutras))}`
              : ''}
          </p>
          {novas.length > 0 ? (
            <p className="importacao-pecas-resumo__acao">
              {(hubT as any).importacaoAnaliseAcao ||
                'Clique «Importar catálogo colado» para enviar apenas as peças novas para a fila amarela.'}
            </p>
          ) : (
            <p className="importacao-pecas-resumo__aviso">
              {(hubT as any).importacaoAnaliseNenhumaNova ||
                'Nenhuma peça nova pode ser importada — todas já existem ou foram ignoradas. Use «Limpar colagem» abaixo para colar outra página.'}
            </p>
          )}
          <div className="importacao-pecas-resumo__actions">
            <button
              type="button"
              className="biblioteca-btn--orange importacao-pecas-limpar-colagem-btn"
              onClick={limparEstadoColagemImportacao}
            >
              🗑️ {(hubT as any).importacaoLimparColagem || 'Limpar colagem e análise'}
            </button>
          </div>
        </div>

        {duplicadasCatalogo.length > 0 ? (
          <section className="importacao-pecas-secao importacao-pecas-secao--vermelho">
            <div className="importacao-pecas-secao__head">
              <span className="importacao-pecas-secao__badge">⛔</span>
              <div>
                <h4>
                  {String(
                    (hubT as any).importacaoJaCadastradasTitulo ||
                      'Já cadastradas na biblioteca ({count})'
                  ).replace('{count}', String(duplicadasCatalogo.length))}
                </h4>
                <p>
                  {(hubT as any).importacaoJaCadastradasDesc ||
                    'Estas peças têm o mesmo código no catálogo gravado — não serão importadas novamente.'}
                </p>
              </div>
            </div>
            {renderTabelaPecas(duplicadasCatalogo, 'vermelho')}
          </section>
        ) : null}

        {duplicadasFila.length > 0 ? (
          <section className="importacao-pecas-secao importacao-pecas-secao--vermelho importacao-pecas-secao--fila">
            <div className="importacao-pecas-secao__head">
              <span className="importacao-pecas-secao__badge">⚠️</span>
              <div>
                <h4>
                  {String(
                    (hubT as any).importacaoJaNaFilaTitulo || 'Já na fila amarela ({count})'
                  ).replace('{count}', String(duplicadasFila.length))}
                </h4>
                <p>
                  {(hubT as any).importacaoJaNaFilaDesc ||
                    'Estas peças já aguardam confirmação (Salvar) — não serão duplicadas.'}
                </p>
              </div>
            </div>
            {renderTabelaPecas(duplicadasFila, 'vermelho')}
          </section>
        ) : null}

        {novas.length > 0 ? (
          <section className="importacao-pecas-secao importacao-pecas-secao--amarelo">
            <div className="importacao-pecas-secao__head">
              <span className="importacao-pecas-secao__badge">✅</span>
              <div>
                <h4>
                  {String(
                    (hubT as any).importacaoNovasTitulo || 'Novas para cadastrar ({count})'
                  ).replace('{count}', String(novas.length))}
                </h4>
                <p>
                  {(hubT as any).importacaoNovasDesc ||
                    'Serão enviadas para a fila amarela ao importar. Depois abra cada uma e use Salvar.'}
                </p>
              </div>
            </div>
            {renderTabelaPecas(novas, 'amarelo')}
          </section>
        ) : null}

        {(duplicadasLote.length > 0 || semCodigo.length > 0) && (
          <p className="importacao-pecas-resumo__extra">
            {montarMensagemImportacaoIgnoradas({
              duplicadasCatalogo: [],
              duplicadasFila: [],
              duplicadasLote,
              semCodigo,
            })}
          </p>
        )}
      </div>
    )
  }, [
    importacaoPreview,
    importacaoAnaliseColagem,
    safeT,
    pecaBibliotecaSrcImagemDisplay,
    montarMensagemImportacaoIgnoradas,
    limparEstadoColagemImportacao,
  ])

  useEffect(() => {
    if (!importacaoPreview?.length && !importacaoAnaliseColagem?.totalColagem) return
    const el = importacaoPreviewPanelRef.current
    if (!el) return
    window.requestAnimationFrame(() => {
      el.scrollIntoView({ behavior: 'smooth', block: 'nearest' })
    })
  }, [importacaoPreview, importacaoAnaliseColagem])

  useEffect(() => {
    const raw = importacaoTextoColado.trim()
    if (raw.length < 12) {
      if (!raw.length) {
        setImportacaoPreview(null)
        setImportacaoAnaliseColagem(null)
        setImportacaoDuplicadasIgnoradas(0)
      }
      return
    }
    const lineCount = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).length
    const shouldAutoPreview =
      raw.startsWith('[') ||
      raw.startsWith('{') ||
      /<table\b/i.test(raw) ||
      lineCount >= 2 ||
      raw.length >= 60
    if (!shouldAutoPreview) return

    const timer = window.setTimeout(() => {
      const result = processarTextoImportacaoPecas(raw, raw)
      if ('pecas' in result && result.pecas.length > 0) {
        processarDuplicadosImportacao(result.pecas)
      }
    }, 500)
    return () => window.clearTimeout(timer)
  }, [importacaoTextoColado, processarTextoImportacaoPecas, processarDuplicadosImportacao])

  const catalogoPecasSuspeitoParcial =
    categoriasPecas.length >= 10 &&
    pecasBiblioteca.length < Math.max(15, Math.min(categoriasPecas.length, 80))

  const pecasReporManualLockRef = useRef(false)

  const gravarBibliotecaUltimaSyncServidor = useCallback((iso?: string) => {
    const at = iso || new Date().toISOString()
    try {
      localStorage.setItem(BIBLIOTECA_ULTIMA_SYNC_KEY, at)
    } catch {
      /* ignore */
    }
    setBibliotecaUltimaSyncServidor(at)
  }, [])

  const formatBibliotecaSyncData = useCallback((iso: string) => {
    if (!iso || iso === 'null') return ''
    try {
      return new Date(iso).toLocaleString(localeForLongDatetime(selectedLanguage))
    } catch {
      return iso
    }
  }, [selectedLanguage])

  const refreshBibliotecaServidorMeta = useCallback(async () => {
    setBibliotecaServidorMetaLoading(true)
    try {
      const meta = await fetchPecasBibliotecaServerMeta()
      if (meta) {
        setBibliotecaServidorMeta({
          total: meta.total,
          totalImages: meta.totalImages,
          totalBase64: meta.totalBase64,
          totalUrl: meta.totalUrl,
          totalPlaceholder: meta.totalPlaceholder,
          totalSemImagem: meta.totalSemImagem,
          totalFaltamFoto: meta.totalFaltamFoto,
          comFotoReal: meta.comFotoReal,
        })
      } else {
        setBibliotecaServidorMeta(null)
      }
    } finally {
      setBibliotecaServidorMetaLoading(false)
    }
  }, [])

  const handleReporPecasBibliotecaDoServidor = useCallback(async () => {
    if (pecasReporManualLockRef.current || pecasBibliotecaReparoLoading) return
    pecasReporManualLockRef.current = true
    setPecasBibliotecaReparoLoading(true)
    setPecasBibliotecaReparoProgress('A ligar ao servidor…')
    try {
      const fromServer = await reporPecasBibliotecaEmergencia((msg) => {
        setPecasBibliotecaReparoProgress(msg)
      })
      if (!Array.isArray(fromServer) || fromServer.length < 50) {
        alert(
          `Não foi possível carregar as peças do servidor.\n\nVerifique:\n• A janela do servidor está aberta (npm run dev)\n• O endereço é http://localhost:3000\n• Prima Ctrl+Shift+R e tente outra vez`
        )
        return
      }
      const raw = (fromServer as PecaBiblioteca[]).map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca))
      const { lista } = garantirNumerosSequenciaPecaBiblioteca(raw, categoriasPecas)
      setPecasBiblioteca(lista)
      await savePecasBibliotecaLocally(lista as unknown[])
      gravarBibliotecaUltimaSyncServidor()
      gravarUltimoServidorTotalAvisado(lista.length)
      void refreshBibliotecaServidorMeta()
      alert(`Biblioteca reposta: ${lista.length} peça(s) com nomes, códigos e fotos do servidor.\n\nNão precisa ir buscar nada ao site outra vez.`)
    } catch (e) {
      console.error('[repor biblioteca]', e)
      alert(
        `Erro ao repor: ${e instanceof Error ? e.message : String(e)}\n\nPrima Ctrl+Shift+R e clique outra vez em Repor biblioteca.`
      )
    } finally {
      pecasReporManualLockRef.current = false
      setPecasBibliotecaReparoLoading(false)
      setPecasBibliotecaReparoProgress('')
    }
  }, [categoriasPecas, pecasBibliotecaReparoLoading, gravarBibliotecaUltimaSyncServidor, refreshBibliotecaServidorMeta])

  /** Se o arranque ficou com 0 peças mas o recuperador gravou no browser, repor na hora. */
  const pecasPosBootReporRef = useRef(false)
  useEffect(() => {
    if (typeof window === 'undefined') return
    if (appInitialLoading) return
    if (pecasPosBootReporRef.current) return
    if (categoriasPecas.length < 10) return
    const minOk = Math.max(15, Math.min(categoriasPecas.length, 80))
    if (pecasBiblioteca.length >= minOk) return
    pecasPosBootReporRef.current = true
    void (async () => {
      try {
        const local = await loadPecasBibliotecaFromBrowserStorage()
        if (local && local.length >= minOk) {
          const raw = (local as PecaBiblioteca[]).map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca))
          const { lista } = garantirNumerosSequenciaPecaBiblioteca(raw, categoriasPecas)
          setPecasBiblioteca(lista)
          console.info(`[Nonato] Biblioteca reposta do browser: ${lista.length} peça(s).`)
          return
        }
        setPecasBibliotecaReparoLoading(true)
        setPecasBibliotecaReparoProgress('A repor biblioteca…')
        const rep = await reporPecasBibliotecaEmergencia((msg) => setPecasBibliotecaReparoProgress(msg))
        if (Array.isArray(rep) && rep.length >= minOk) {
          const raw = (rep as PecaBiblioteca[]).map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca))
          const { lista } = garantirNumerosSequenciaPecaBiblioteca(raw, categoriasPecas)
          setPecasBiblioteca(lista)
        }
      } catch (e) {
        console.warn('[Nonato] Repor pós-arranque:', e)
      } finally {
        setPecasBibliotecaReparoLoading(false)
        setPecasBibliotecaReparoProgress('')
      }
    })()
  }, [appInitialLoading, categoriasPecas, pecasBiblioteca.length])

  const persistPecasBiblioteca = useCallback((next: PecaBiblioteca[]) => {
    const normalizado = next.map((peca) => sanitizarPecaBibliotecaImportacaoFlag(peca))
    const semCodigoRepetido = deduplicarPecasBibliotecaPorCodigo(normalizado)
    const rejeitadosPorCodigo = normalizado.length - semCodigoRepetido.length
    if (rejeitadosPorCodigo > 0) {
      console.info(
        `[pecas biblioteca] ${rejeitadosPorCodigo} duplicado(s) por código fundido(s) — classificação preservada.`
      )
    }
    const { lista: comNumeros } = garantirNumerosSequenciaPecaBiblioteca(semCodigoRepetido, categoriasPecas)
    setPecasBiblioteca(comNumeros)
    void saveData('nonato-pecas-biblioteca', comNumeros, true, true).catch((err) => {
      console.error('[pecas biblioteca]', err)
      alert(
        (t as any)?.importacaoErroGravarFila ??
          'Não foi possível gravar na biblioteca no servidor. Os dados ficaram neste aparelho — verifique ligação ou volume Railway (/app/data).'
      )
    })
  }, [t, categoriasPecas])

  const handleHomagExportMergeFicheiro = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file) return
      setHomagMergeLoading(true)
      setImportacaoUrlError(null)
      const reader = new FileReader()
      reader.onload = () => {
        try {
          const incoming = parseHomagExportJson(String(reader.result ?? ''))
          if (incoming.length === 0) {
            alert(
              (t as any)?.homagSyncExportVazio ||
                'O ficheiro export.json está vazio. Execute primeiro IMPORTAR-TUDO-HOMAG.bat no PC.'
            )
            return
          }
          const filaPendente = pecasBiblioteca.filter((p) => ehImportacaoPendenteStrict(p))
          const catalogo = pecasBiblioteca.filter(pecaBibliotecaEstaNoCatalogo)
          const result = mergeHomagExportIntoBiblioteca(catalogo, incoming, {
            substituirFotosExistentes: homagSubstituirFotos,
          })
          persistPecasBiblioteca([...result.list, ...filaPendente])
          setHomagUltimoSync({
            added: result.added,
            updatedImages: result.updatedImages,
            updatedNames: result.updatedNames,
            updatedPrecos: result.updatedPrecos,
            total: result.list.length,
            at: new Date().toLocaleString('pt-PT'),
          })
          const msg = String(
            (t as any)?.homagSyncSucesso ||
              'Actualização HOMAG concluída:\n\n• {added} peça(s) nova(s)\n• {fotos} foto(s) actualizada(s)\n• {precos} preço(s) actualizado(s)\n• {nomes} nome(s) preenchido(s)\n• Total no catálogo: {total}'
          )
            .replace('{added}', String(result.added))
            .replace('{fotos}', String(result.updatedImages))
            .replace('{precos}', String(result.updatedPrecos))
            .replace('{nomes}', String(result.updatedNames))
            .replace('{total}', String(result.list.length))
          alert(msg)
        } catch (err: unknown) {
          const m = err instanceof Error ? err.message : String(err)
          alert(`${(t as any)?.homagSyncErro || 'Erro ao actualizar com export HOMAG:'}\n\n${m}`)
        } finally {
          setHomagMergeLoading(false)
        }
      }
      reader.readAsText(file, 'UTF-8')
      e.target.value = ''
    },
    [pecasBiblioteca, homagSubstituirFotos, persistPecasBiblioteca, t]
  )

  const handleDeletePecaBiblioteca = useCallback(
    (pecaId: string) => {
      if (!window.confirm(t.confirmDeletePecaBiblioteca || 'Tem certeza que deseja excluir esta peça?')) return
      persistPecasBiblioteca(pecasBiblioteca.filter((p) => p.id !== pecaId))
    },
    [t, persistPecasBiblioteca, pecasBiblioteca]
  )

  const handleLimparFilaImportacaoPendente = useCallback(
    (ids?: string[]) => {
      const onlyIds = Array.isArray(ids) && ids.length > 0 ? new Set(ids) : null
      const pendentes = pecasBiblioteca.filter((p) => ehImportacaoPendenteStrict(p))
      const alvo = onlyIds ? pendentes.filter((p) => onlyIds.has(p.id)) : pendentes
      if (alvo.length === 0) {
        alert((t as any)?.importacaoNenhumaPendenteParaLimpar || 'Nenhuma peça pendente para limpar.')
        return
      }
      const confirmMsg =
        (t as any)?.importacaoConfirmarLimparFila ||
        'Tem certeza que deseja limpar a fila de importação? Esta ação apaga as peças pendentes (ainda não salvas) e não pode ser desfeita.'
      if (!window.confirm(`${confirmMsg}\n\n${alvo.length} item(ns).`)) return
      const toRemove = new Set(alvo.map((p) => p.id))
      persistPecasBiblioteca(pecasBiblioteca.filter((p) => !toRemove.has(p.id)))
      if (editingPecaBiblioteca && toRemove.has(editingPecaBiblioteca.id)) {
        setEditingPecaBiblioteca(null)
        setShowBibliotecaPecasForm(false)
        setSalvarPecaBibliotecaVoltaParaImportacao(false)
      }
    },
    [editingPecaBiblioteca, pecasBiblioteca, persistPecasBiblioteca, t]
  )

  const persistRegrasClassificacaoPecas = useCallback((next: RegraClassificacaoPeca[]) => {
    setRegrasClassificacaoPecas(next)
    localStorage.setItem('nonato-regras-classificacao-pecas', JSON.stringify(next))
    void saveData('nonato-regras-classificacao-pecas', next)
  }, [])

  /** Renomear grupo: atualiza também o texto nas peças e nas regras de classificação automática. */
  const renomearCategoriaPecaBiblioteca = useCallback(
    (categoriaId: string, novoNome: string) => {
      const nome = novoNome.trim()
      if (!nome) return
      setCategoriasPecas(prev => {
        const next = prev.map(c => (c.id === categoriaId ? { ...c, nome } : c))
        void saveData('nonato-categorias-pecas', next)
        return next
      })
      const nextPecas = pecasBiblioteca.map(p =>
        p.categoriaId === categoriaId ? { ...p, categoria: nome } : p
      )
      persistPecasBiblioteca(nextPecas)
      setPecaBibliotecaForm(prev =>
        prev.categoriaId === categoriaId ? { ...prev, categoria: nome } : prev
      )
      const nextRegras = regrasClassificacaoPecas.map(r =>
        r.categoriaId === categoriaId ? { ...r, categoria: nome } : r
      )
      persistRegrasClassificacaoPecas(nextRegras)
    },
    [pecasBiblioteca, regrasClassificacaoPecas, persistPecasBiblioteca, persistRegrasClassificacaoPecas]
  )

