      coloreAltro: '',
      dimensioniMax: '',
      dimensioniMin: '',
      dimensioniAltro: '',
      tipologiaBordo: [],
      tipologiaBordoAltro: '',
      spessoreBordo: [],
      spessoreBordoAltro: '',
      tipoColla: [],
      tipoCollaAltro: '',
      griglieProtezione: [],
      griglieProtezioneAggiunte: false,
      utensiliFornitiCliente: false,
