                          const pecasManuais = [{ codigo: pecaSelecionadaParaChecklist.codigo, quantia: 1 }]
                          setGruposChecklist(prev => {
                            const next = prev.map(g => g.id !== grupoId ? g : { ...g, itensTrabalho: (g.itensTrabalho || []).map(i => i.id !== itemId ? i : { ...i, origemPecas: 'biblioteca' as const, codigoPeca: pecaSelecionadaParaChecklist!.codigo, pecasManuais } as ItemTrabalhoCriacao) })
                            saveData('nonato-grupos-checklist', next)
                            return next
                          })
                          setCriacaoChecklistPendentePeca(null)
                          setPecaSelecionadaParaChecklist(null)
                          setCriacaoChecklistEditingItemPecasId(null)
                          openTab('familias-grupos', getTabTitle('familias-grupos'))
