                                width: '100%',
                                padding: '15px 20px',
                                backgroundColor: 'rgba(0, 100, 255, 0.2)',
                                border: '1px solid rgba(0, 100, 255, 0.85)',
                                borderRadius: '8px',
                                color: '#ffffff',
                                cursor: 'pointer',
